// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"dabigatran":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es das zentrale Gerinnungsenzym Thrombin direkt blockiert. Eingenommen wird die unwirksame Vorstufe Dabigatranetexilat (Prodrug), die im Körper durch Esterasen rasch in Dabigatran umgewandelt wird. Dabigatran hemmt freies und an Gerinnsel gebundenes Thrombin reversibel und verhindert so die Bildung von Fibrin und die thrombinbedingte Aktivierung der Blutplättchen. Es wird zu rund 80 % unverändert über die Nieren ausgeschieden; als spezifisches Gegenmittel steht Idarucizumab zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Nasenbluten","Magen-Darm-Blutungen","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Übelkeit","Hautblutungen","Blutungen der Harn- und Geschlechtsorgane, Blut im Urin"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeit, Hautausschlag, Juckreiz","Blutergüsse (Hämatome), Bluthusten","Magen-Darm-Geschwüre, Entzündung der Speiseröhre, Reflux, Schluckbeschwerden, Erbrechen","Blutungen aus Enddarm und Hämorrhoiden","Leberfunktionsstörung, erhöhte Leberwerte"],"selten":["Anaphylaktische Reaktion, Angioödem, Nesselsucht","Gelenkblutungen","Blutungen an Einstich-, Katheter- und Wundstellen"],"unbekannt":["Agranulozytose, Neutropenie (Mangel an weissen Blutkörperchen)","Bronchospasmus","Haarausfall"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich. Frauen im gebärfähigen Alter sollen während der Behandlung eine Schwangerschaft vermeiden.","stillzeit":"Keine Daten beim Menschen – während der Behandlung nicht stillen.","hinweise":["Kapseln ganz mit Wasser schlucken, nicht öffnen oder zerkauen – der Inhalt wird sonst viel stärker aufgenommen (Blutungsgefahr).","Kapseln in der Originalverpackung (Blister) lassen und vor Feuchtigkeit schützen.","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen, bei älteren Menschen mindestens jährlich.","Nicht eigenmächtig absetzen; vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren."],"darreichung":["Hartkapseln"]},"dalteparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Dalteparin ist ein aus Heparin gewonnenes niedermolekulares Heparin: Es verstärkt die Wirkung des körpereigenen Hemmstoffs Antithrombin, der vor allem den Gerinnungsfaktor Xa und in geringerem Mass Thrombin (Faktor IIa) blockiert. Im Vergleich zu unfraktioniertem Heparin wirkt es gleichmässiger und länger, sodass ein bis zwei Spritzen unter die Haut pro Tag genügen. Die Wirkung lässt sich über die Anti-Xa-Aktivität messen; die Ausscheidung erfolgt überwiegend über die Nieren.","nebenwirkungen":{"haeufig":["Blutungen","Bluterguss (Hämatom) und Schmerzen an der Einstichstelle","Leichte, meist vorübergehende Abnahme der Blutplättchen (Thrombozytopenie Typ I)","Vorübergehender Anstieg der Leberwerte (Transaminasen)"],"gelegentlich":["Überempfindlichkeitsreaktionen"],"selten":["Hautnekrosen (absterbende Haut) an der Einstichstelle","Vorübergehender Haarausfall"],"unbekannt":["Heparininduzierte Thrombozytopenie Typ II (HIT; immunbedingt, mit oder ohne Thrombosen)","Anaphylaktische Reaktionen","Hirnblutungen und Blutungen im hinteren Bauchraum (retroperitoneal), teils tödlich","Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie mit möglicher Lähmung","Hautausschlag"]},"schwangerschaft":"Dalteparin passiert die Plazenta nicht; bisherige Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung nach ärztlicher Abwägung möglich; eine rückenmarksnahe Anästhesie bei der Geburt muss zeitlich abgestimmt werden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling über den Darm kaum aufgenommen; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Unter die Haut spritzen (meist am Bauch), nie in den Muskel; Einstichstelle wechseln und nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen","Injektionslösung in Ampullen"]},"dapagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren überschüssigen Zucker mit dem Urin ausscheiden. Dapagliflozin hemmt selektiv und reversibel den Natrium-Glukose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glukose in den Körper zurückholt. Die Wirkung ist unabhängig vom Insulin; zusätzlich entstehen eine leichte osmotische Diurese, eine vermehrte Natriumausscheidung, ein Kalorienverlust und eine mässige Blutdrucksenkung. Bei Herz- und Nierenkrankheit tragen vermutlich die Senkung des Drucks in den Nierenkörperchen (tubuloglomerulärer Feedback) und die Entlastung des Herzens zur Schutzwirkung bei.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Genitalinfektionen wie Scheidenpilz (Vulvovaginitis) oder Eichelentzündung (Balanitis)","Harnwegsinfekte","Vermehrtes Wasserlassen (Polyurie), Brennen beim Wasserlassen (Dysurie)","Schwindel","Hautausschlag","Rückenschmerzen","Anstieg von Hämatokrit und Blutfetten, vorübergehender Rückgang der Nierenfunktion zu Therapiebeginn"],"gelegentlich":["Volumenmangel (Austrocknung, tiefer Blutdruck)","Durst, Mundtrockenheit","Verstopfung","Nächtliches Wasserlassen (Nykturie)","Juckreiz im Genitalbereich","Gewichtsabnahme","Anstieg von Kreatinin und Harnstoff im Blut"],"selten":["Diabetische Ketoazidose (lebensbedrohliche Übersäuerung, auch bei fast normalem Blutzucker)"],"sehrSelten":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Tubulointerstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Nicht anwenden: im 2. und 3. Schwangerschaftsdrittel nicht empfohlen (Nierenschäden im Tierversuch). Bei Eintritt einer Schwangerschaft absetzen und ärztlich auf eine andere Behandlung umstellen.","stillzeit":"Nicht anwenden, da ein Übergang in die Muttermilch und Auswirkungen auf das gestillte Kind nicht ausgeschlossen werden können.","hinweise":["Der Urin-Zuckertest fällt unter der Behandlung immer positiv aus – zur Kontrolle den Blutzucker messen.","Bei akuten Erkrankungen mit Erbrechen, Durchfall oder wenig Trinken sowie vor grösseren Operationen nach ärztlicher Anweisung pausieren (Ketoazidose- und Austrocknungsgefahr).","Warnzeichen einer Ketoazidose (Übelkeit, Erbrechen, Bauchschmerzen, starker Durst, rasche Atmung, Verwirrtheit, ungewöhnliche Müdigkeit) sofort ärztlich abklären lassen.","Ausreichend trinken und auf Intimhygiene achten; Einnahme einmal täglich, unabhängig von den Mahlzeiten."],"darreichung":["Filmtabletten","Retardtabletten (Kombination mit Metformin)"]},"dapoxetin":{"wirkmechanismus":"Verzögert den Samenerguss. Dapoxetin hemmt die Wiederaufnahme von Serotonin in die Nervenzellen und verstärkt so die Serotoninwirkung im Gehirn, die den Ejakulationsreflex zentral bremst. Es wird rasch aufgenommen und rasch ausgeschieden; deshalb wird es nur bei Bedarf 1–3 Stunden vor dem Geschlechtsverkehr eingenommen.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Übelkeit"],"haeufig":["Angst, Unruhe, Schlafstörungen","Schläfrigkeit, Konzentrationsstörungen, Zittern","Verschwommenes Sehen","Durchfall, Erbrechen, Verstopfung, Bauchschmerzen","Mundtrockenheit","Vermehrtes Schwitzen","Erektionsstörung, verminderte Libido","Müdigkeit, Reizbarkeit"],"gelegentlich":["Synkope (Ohnmacht), auch mit Sturzverletzungen","Blutdruckabfall, Schwindel beim Aufstehen","Verlangsamter Herzschlag, kurze Herzpausen (Sinusarrest), Herzrasen","Depressive Verstimmung, Verwirrtheit","Pupillenerweiterung, Sehstörungen","Ejakulations- und Orgasmusstörungen"],"selten":["Plötzliches Einschlafen","Schwindel bei körperlicher Anstrengung","Plötzlicher Stuhldrang"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["1–3 Stunden vor dem Geschlechtsverkehr mit mindestens einem vollen Glas Wasser einnehmen, höchstens einmal in 24 Stunden.","Bei Vorzeichen einer Ohnmacht (Schwindel, Benommenheit, Schwitzen) sofort hinlegen; nicht Auto fahren, wenn solche Beschwerden auftreten.","Keinen Alkohol und keine Drogen dazu einnehmen.","Nach 4 Wochen bzw. mindestens 6 Einnahmen den Nutzen ärztlich beurteilen lassen."],"darreichung":["Filmtabletten"]},"daptomycin":{"wirkmechanismus":"Durchlöchert die Hülle von Bakterien und tötet sie rasch ab. Daptomycin lagert sich calciumabhängig in die Zellmembran grampositiver Bakterien ein, führt zu einer raschen Depolarisation und stoppt die Synthese von DNA, RNA und Eiweissen. Es wirkt auch gegen Methicillin-resistente Staphylokokken (MRSA) und Vancomycin-resistente Enterokokken. In der Lunge wird es durch das Surfactant inaktiviert und ist deshalb gegen Lungenentzündungen unwirksam.","nebenwirkungen":{"haeufig":["Pilzinfektionen, Harnwegsinfektionen","Anämie (Blutarmut)","Angst, Schlaflosigkeit","Schwindel, Kopfschmerzen","Bluthochdruck oder tiefer Blutdruck","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verstopfung, Blähungen","Erhöhte Leberwerte und erhöhte Kreatinkinase (CK)","Ausschlag, Juckreiz, Gliederschmerzen, Reaktionen an der Infusionsstelle, Fieber"],"gelegentlich":["Eosinophilie, Thrombozythämie, erhöhte INR","Appetitlosigkeit, Hyperglykämie, Elektrolytstörungen","Kribbeln, Geschmacksstörungen, Zittern","Herzrhythmusstörungen (supraventrikuläre Tachykardie, Extrasystolen)","Myositis, Muskelschwäche, Muskel- und Gelenkschmerzen","Nierenfunktionsstörung bis Nierenversagen","Nesselsucht"],"selten":["Gelbsucht (Ikterus)","Verlängerte Prothrombinzeit"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Eosinophile Pneumonie, organisierende Pneumonie","Anaphylaxie, Angioödem, DRESS (schwere Arzneimittelreaktion)","Schwere bullöse Hautreaktionen, akute generalisierte exanthematische Pustulose (AGEP)","Periphere Neuropathie","Clostridioides-difficile-assoziierte Durchfälle","Tubulointerstitielle Nephritis"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung in der Stillzeit nur nach ärztlicher Abwägung, Stillen allenfalls unterbrechen.","hinweise":["Wird im Spital oder ambulant als Infusion bzw. Injektion einmal täglich verabreicht.","Muskelschmerzen, Muskelschwäche, Kribbeln oder Taubheit sowie neue Atemnot mit Fieber sofort melden.","Kreatinkinase (CK) wird mindestens wöchentlich kontrolliert, bei Risikopatienten häufiger."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"daratumumab":{"wirkmechanismus":"Markiert Myelomzellen, damit das Immunsystem sie zerstört. Daratumumab ist ein humaner monoklonaler IgG1-Antikörper gegen CD38, ein Eiweiss, das auf Myelom- und Plasmazellen in grosser Menge vorkommt. Er tötet die Tumorzellen über das Komplementsystem, über Immunzellen (antikörperabhängige Zytotoxizität und Phagozytose) und durch Auslösen des programmierten Zelltods; zudem vermindert er immunhemmende Zellen, die CD38 tragen. Weil auch rote Blutkörperchen etwas CD38 tragen, stört der Antikörper die Verträglichkeitstests vor Bluttransfusionen.","nebenwirkungen":{"sehrHaeufig":["Infektionen: Lungenentzündung, Bronchitis, obere Atemwege","Neutropenie, Thrombozytopenie, Anämie, Lymphopenie","Infusionsreaktionen (Husten, Atemnot, Schüttelfrost, verstopfte Nase, Übelkeit)","Periphere sensorische Neuropathie, Kopfschmerzen","Durchfall, Verstopfung, Übelkeit, Erbrechen","Müdigkeit, Fieber, periphere Ödeme, Schwäche","Rückenschmerzen, Muskelkrämpfe"],"haeufig":["Sepsis, Harnwegsinfekte, Grippe, Zytomegalievirus-Infektion","Vorhofflimmern","Lungenödem","Hyperglykämie, Hypokalzämie, Austrocknung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hautausschlag, Juckreiz","Synkope (Ohnmacht)","Reaktionen an der Injektionsstelle (subkutane Form)"],"gelegentlich":["Hepatitis-B-Reaktivierung"],"selten":["Anaphylaktische Reaktion"]},"schwangerschaft":"Nur bei zwingender Indikation (der Antikörper kann beim Kind Blutzellen vermindern). Frauen müssen während und bis 3 Monate nach der Behandlung sicher verhüten.","stillzeit":"Unbekannt, ob der Antikörper in die Muttermilch übergeht; nach ärztlicher Abwägung zwischen Stillen und Behandlung entscheiden.","hinweise":["Vor Beginn werden Blutgruppe und Antikörpersuchtest bestimmt; bei jeder Bluttransfusion – bis 6 Monate nach der letzten Gabe – auf die Behandlung hinweisen (Patientenausweis).","Vor jeder Gabe Vorbehandlung mit Kortikosteroid, Antihistaminikum und Paracetamol; Reaktionen sind auch Stunden später möglich.","Fieber oder Infektzeichen sofort melden; vor Beginn Test auf Hepatitis B."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung"]},"darbepoetin-alfa":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Darbepoetin alfa wirkt wie das körpereigene Hormon Erythropoetin am Erythropoetin-Rezeptor der Vorläuferzellen im Knochenmark. Durch zwei zusätzliche Zuckerketten im Molekül wird es langsamer abgebaut und hat eine etwa dreimal längere Halbwertszeit als Epoetin alfa. Deshalb genügen Spritzen in Abständen von einer bis vier Wochen; ausreichend Eisen ist Voraussetzung für die Wirkung.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck (bei Nierenkranken)","Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht)","Wassereinlagerungen (Ödeme, bei Krebspatienten)"],"haeufig":["Schlaganfall (bei Nierenkranken)","Thrombosen und Embolien, inkl. Lungenembolie (bei Krebspatienten)","Hautrötung (Erythem)","Schmerzen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle","Thrombose des Dialyse-Shunts"],"unbekannt":["Erythroblastopenie (PRCA) durch Antikörper gegen Erythropoetin","Hypertensive Krise mit Hirnfunktionsstörung (Enzephalopathie)","Anaphylaxie, Angioödem (Schwellung von Gesicht und Rachen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; Erfahrungen beim Menschen fehlen weitgehend.","stillzeit":"Nicht bekannt, ob Darbepoetin in die Muttermilch übergeht; Anwendung nur nach Abwägung.","hinweise":["Blutdruck regelmässig messen; bei starken Kopfschmerzen, Verwirrtheit oder Sehstörungen sofort ärztliche Hilfe holen.","Hämoglobin und Eisenwerte werden regelmässig kontrolliert; meist ist zusätzlich Eisen nötig.","Im Kühlschrank (2–8 °C) lagern, nicht einfrieren oder schütteln.","Missbrauch als Dopingmittel ist verboten und gefährlich (Thrombosen, Herzinfarkt)."],"darreichung":["Injektionslösung in Fertigspritzen und Fertigpens (Spritze unter die Haut oder in die Vene)"]},"daridorexant":{"wirkmechanismus":"Fördert den Schlaf, indem es das Wachsignal des Gehirns dämpft, statt das Gehirn allgemein zu betäuben. Daridorexant blockiert beide Orexin-Rezeptoren (OX1R und OX2R) und verhindert so, dass die wachheitsfördernden Botenstoffe Orexin A und B andocken. Die Halbwertszeit beträgt etwa 8 Stunden; der Abbau erfolgt überwiegend über CYP3A4.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit (auch am Folgetag), Müdigkeit","Schwindel","Übelkeit"],"gelegentlich":["Schlaflähmung (vorübergehende Unfähigkeit, sich beim Einschlafen oder Aufwachen zu bewegen)","Halluzinationen beim Einschlafen oder Aufwachen"]},"schwangerschaft":"Kaum Erfahrungen; nur anwenden, wenn der Zustand der Frau es zwingend erfordert.","stillzeit":"Nicht bekannt, ob Daridorexant in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nur nach ärztlicher Abwägung, das Kind auf Schläfrigkeit beobachten.","hinweise":["Abends etwa 30 Minuten vor dem Zubettgehen einnehmen; eine Einnahme kurz nach einer Mahlzeit kann den Wirkungseintritt verzögern.","Keinen Alkohol trinken; Grapefruitsaft meiden.","Am Folgetag kann die Fahrtüchtigkeit beeinträchtigt sein – kein Fahrzeug lenken, wenn man sich nicht vollständig wach fühlt.","Die Notwendigkeit der Behandlung innerhalb von 3 Monaten ärztlich überprüfen lassen."],"darreichung":["Filmtabletten"]},"darifenacin":{"wirkmechanismus":"Entspannt die Blasenmuskulatur und vermindert so Harndrang und häufiges Wasserlassen. Darifenacin blockiert selektiv den Muskarin-M3-Rezeptor, über den der Blasenmuskel (Detrusor) zur Kontraktion angeregt wird. Dadurch nimmt die Blasenkapazität zu, und unwillkürliche Blasenkontraktionen werden gedämpft. Wegen der M3-Selektivität sind Wirkungen an Herz und Gehirn geringer, aber nicht ausgeschlossen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Obstipation (Verstopfung)"],"haeufig":["Kopfschmerzen","Trockene Augen","Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Bauchschmerzen","Trockene Nasenschleimhaut"],"gelegentlich":["Harnverhalt","Harnwegsinfekt","Schwindel, Schläfrigkeit","Verschwommenes Sehen","Geschmacksstörung","Bluthochdruck","Hautausschlag, Juckreiz","Erhöhte Leberwerte"],"unbekannt":["Verwirrtheit","Halluzinationen","Depressive Verstimmung, Stimmungsschwankungen","Angioödem (Schwellung von Gesicht und Rachen)"]},"schwangerschaft":"Nicht empfohlen, da nur begrenzte Daten vorliegen.","stillzeit":"Nur nach ärztlicher Abwägung; bei Tieren geht Darifenacin in die Milch über.","hinweise":["Retardtabletten unzerkaut mit Flüssigkeit schlucken, unabhängig von den Mahlzeiten.","Schwindel und verschwommenes Sehen sind möglich – Vorsicht beim Autofahren.","Bei anhaltender Verstopfung oder Schwierigkeiten beim Wasserlassen ärztlich abklären."],"darreichung":["Retardtabletten"]},"darunavir":{"wirkmechanismus":"Verhindert, dass neu gebildete HI-Viren reifen und weitere Zellen infizieren. Darunavir hemmt die HIV-1-Protease, ein Enzym, das die viralen Gag-Pol-Vorläuferproteine in funktionsfähige Einzelproteine zerschneidet; es entstehen nur unreife, nicht infektiöse Viruspartikel. Darunavir bindet sehr fest an das Enzym und wirkt auch bei vielen Resistenzen gegen ältere Proteasehemmer. Weil es rasch über CYP3A4 abgebaut wird, wird es immer mit einem «Booster» (Ritonavir oder Cobicistat) kombiniert, der diesen Abbau hemmt – das erklärt die zahlreichen Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen, Blähungen, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Schlaflosigkeit","Hautausschlag, Juckreiz","Erhöhte Blutfette (Cholesterin, Triglyceride), Diabetes mellitus","Erhöhte Leberwerte (ALT) und Amylase","Müdigkeit, Schwäche"],"gelegentlich":["Hepatitis (Leberentzündung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Herzinfarkt, Angina pectoris, QT-Verlängerung","Angioödem, Nesselsucht","Thrombozytopenie, Neutropenie, Anämie","Depression, Angst, Desorientierung","Akutes Nierenversagen, Nierensteine","Osteonekrose, Muskelschmerzen, Gynäkomastie (Brustvergrösserung beim Mann)"],"selten":["Stevens-Johnson-Syndrom","DRESS (schwere Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Erythema multiforme","Krampfanfälle, Ohnmacht","Kristallnephropathie (Ablagerung von Darunavir-Kristallen in der Niere)"],"unbekannt":["Toxische epidermale Nekrolyse","Akute generalisierte exanthematische Pustulose (AGEP)"]},"schwangerschaft":"Darunavir mit Ritonavir kann in der Schwangerschaft angewendet werden, wenn der Nutzen das Risiko rechtfertigt. Darunavir mit Cobicistat wird wegen zu tiefer Spiegel in der Schwangerschaft nicht empfohlen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Immer zusammen mit Ritonavir oder Cobicistat und mit einer Mahlzeit einnehmen (bessere Aufnahme).","Vor jedem neuen Medikament – auch rezeptfreien und pflanzlichen wie Johanniskraut – mit Ärztin, Arzt oder Apotheke Rücksprache nehmen.","Täglich ohne Unterbrechung einnehmen, damit keine Resistenzen entstehen.","Bei schwerem Hautausschlag mit Fieber, Blasen oder Schleimhautbeteiligung sofort ärztlich melden."],"darreichung":["Filmtabletten"]},"delgocitinib":{"wirkmechanismus":"Dämpft Entzündung und Juckreiz der Haut an den Händen. Delgocitinib hemmt alle vier Januskinasen (JAK1, JAK2, JAK3 und TYK2) und blockiert damit die Signalübertragung zahlreicher entzündungsfördernder Botenstoffe über den JAK-STAT-Weg. Dadurch gehen Entzündung und Juckreiz zurück und die gestörte Hautbarriere kann sich erholen. Über die Haut gelangen nur sehr geringe Mengen ins Blut.","nebenwirkungen":{"haeufig":["Reaktionen an der Auftragsstelle (z. B. Schmerzen, Juckreiz, Rötung, Kribbeln)"]},"schwangerschaft":"Nur begrenzte Daten; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Delgocitinib in die Muttermilch übergeht; ein Risiko für den Säugling ist nicht auszuschliessen – nur nach ärztlicher Abwägung.","hinweise":["Zweimal täglich eine dünne Schicht auf die betroffenen Stellen an Händen und Handgelenken auftragen.","Nach dem Auftragen nicht in die Augen fassen.","Rückfettende Handpflege und Schutz vor Reizstoffen (z. B. Handschuhe bei Feuchtarbeit) weiterführen."],"darreichung":["Creme"]},"denosumab":{"wirkmechanismus":"Bremst den Knochenabbau, indem es ein Signal blockiert, das die knochenabbauenden Zellen aktiviert. Denosumab ist ein humaner monoklonaler Antikörper, der an RANKL bindet und so dessen Andocken an den Rezeptor RANK auf Osteoklasten und deren Vorläuferzellen verhindert. Dadurch werden Bildung, Funktion und Überleben der Osteoklasten gehemmt; Knochendichte und -festigkeit nehmen zu. Anders als Bisphosphonate lagert sich Denosumab nicht im Knochen ein – nach dem Absetzen lässt die Wirkung rasch nach.","nebenwirkungen":{"sehrHaeufig":["Glieder-, Muskel- und Knochenschmerzen","Hypokalzämie (Calciummangel; unter Xgeva sehr häufig, unter Prolia selten, aber teils schwer)","Atemnot und Durchfall (unter Xgeva)"],"haeufig":["Harnwegsinfekte und Infekte der oberen Atemwege","Ischiasschmerzen","Verstopfung, Bauchbeschwerden","Hautausschlag, Ekzem, Haarausfall","Kiefernekrose (Absterben von Kieferknochen; unter Xgeva häufig, unter Prolia selten)","Hypophosphatämie (Phosphatmangel) und vermehrtes Schwitzen (unter Xgeva)"],"gelegentlich":["Zellulitis (bakterielle Hautinfektion)","Divertikulitis","Ohrinfektion","Lichenoider Arzneimittelausschlag"],"selten":["Atypische Oberschenkelbrüche","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Osteonekrose des äusseren Gehörgangs"],"unbekannt":["Mehrere Wirbelbrüche nach dem Absetzen von Prolia","Hyperkalzämie nach dem Absetzen bei wachsendem Skelett (Xgeva)"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung und bis mindestens 5 Monate nach der letzten Dosis wirksam verhüten.","stillzeit":"Unbekannt, ob Denosumab in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Zusätzlich Calcium und Vitamin D einnehmen (ausser bei erhöhtem Calcium); der Calciumspiegel wird vor jeder Dosis bzw. bei Nierenerkrankung engmaschig kontrolliert.","Prolia-Spritze alle 6 Monate pünktlich; nie ohne ärztlich geplante Anschlussbehandlung (meist ein Bisphosphonat) absetzen.","Vor Beginn Zahnstatus kontrollieren und auf gute Mundhygiene achten; Zahnbehandlungen mitteilen.","Bei Muskelkrämpfen oder Kribbeln (Calciummangel), geröteter, schmerzhafter Haut mit Fieber oder neuen Oberschenkelschmerzen ärztlichen Rat einholen."],"darreichung":["Injektionslösung (Fertigspritze)","Injektionslösung (Durchstechflasche)"]},"desloratadin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert dadurch Niesen, Fliessschnupfen, Juckreiz und Quaddeln. Desloratadin ist der aktive Hauptmetabolit von Loratadin und ein lang wirksamer, selektiver Antagonist peripherer Histamin-H1-Rezeptoren. In Laborversuchen hemmt es zusätzlich die Freisetzung entzündungsfördernder Botenstoffe aus Mastzellen. Es gelangt kaum ins Gehirn und macht deshalb selten müde.","nebenwirkungen":{"haeufig":["Müdigkeit","Mundtrockenheit","Kopfschmerzen","Bei Kleinkindern: Durchfall, Fieber, Schlaflosigkeit"],"sehrSelten":["Anaphylaxie und andere Überempfindlichkeitsreaktionen","Halluzinationen, Schwindel, Schläfrigkeit, psychomotorische Unruhe","Krampfanfälle","Herzrasen (Tachykardie), Herzklopfen","Bauchschmerzen, Übelkeit, Erbrechen, Verdauungsstörungen","Erhöhte Leberwerte, Hepatitis (Leberentzündung)","Muskelschmerzen"],"unbekannt":["QT-Verlängerung im EKG","Lichtempfindlichkeit der Haut","Verhaltensauffälligkeiten, Aggressivität","Gelbsucht","Gewichtszunahme, Appetitsteigerung"]},"schwangerschaft":"Viele Daten ohne Hinweis auf Fehlbildungen; vorsichtshalber möglichst vermeiden.","stillzeit":"Geht in die Muttermilch über; ärztlich abwägen, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Vor Allergie-Hauttests ärztlich klären, wann abgesetzt werden muss.","Selten Müdigkeit möglich – die eigene Reaktion vor dem Autofahren prüfen."],"darreichung":["Filmtabletten"]},"desmopressin":{"wirkmechanismus":"Bewirkt, dass die Nieren mehr Wasser zurückhalten und weniger, dafür konzentrierteren Urin bilden. Desmopressin ist ein synthetisch abgewandeltes Vasopressin (antidiuretisches Hormon) und aktiviert gezielt die V2-Rezeptoren in den Sammelrohren der Niere; dadurch werden Wasserkanäle (Aquaporine) eingebaut und Wasser zurückgewonnen. Im Gegensatz zu Vasopressin wirkt es kaum gefässverengend und deutlich länger. In höherer Dosis setzt es zudem Gerinnungsfaktor VIII und von-Willebrand-Faktor aus den Gefässwänden frei und verbessert so die Blutgerinnung.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Hyponatriämie (Natriummangel im Blut), v. a. bei Erwachsenen über 65 Jahre","Schwindel","Übelkeit, Bauchschmerzen, Durchfall, Verstopfung, Erbrechen","Mundtrockenheit","Ödeme (Wassereinlagerungen), Müdigkeit"],"gelegentlich":["Schlaflosigkeit oder Schläfrigkeit","Herzklopfen, Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz","Muskelkrämpfe","Gewichtszunahme","Stimmungsschwankungen, Aggressivität (bei Kindern)"],"selten":["Verwirrtheit"],"unbekannt":["Schwere Hyponatriämie mit Krampfanfällen, Hirnödem und Bewusstlosigkeit (Wasservergiftung)","Anaphylaktische Reaktionen","Gesichtsrötung, Pulsanstieg und Blutdruckschwankungen nach Injektion"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Die Erfahrungen bei Schwangeren mit Diabetes insipidus zeigen keine schädlichen Wirkungen auf Schwangerschaft oder Kind.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist in der Regel möglich.","hinweise":["Bei Bettnässen und Nykturie ab 1 Stunde vor bis 8 Stunden nach der Einnahme möglichst wenig trinken – sonst droht eine Wasservergiftung.","Bei Erbrechen, Durchfall, Fieber oder starkem Durst die Einnahme unterbrechen; bei Kopfschmerzen, Übelkeit, Verwirrtheit oder rascher Gewichtszunahme sofort ärztlich das Natrium kontrollieren lassen.","Schmelztabletten unter der Zunge zergehen lassen, ohne Wasser; Tabletten, Schmelztabletten und Nasenspray sind unterschiedlich dosiert und nicht 1:1 austauschbar."],"darreichung":["Tabletten","Schmelztabletten (Lyophilisat)","Nasenspray","Injektionslösung"]},"desogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Desogestrel ist eine Vorstufe (Prodrug) und wird in Darmwand und Leber zum eigentlichen Wirkstoff Etonogestrel umgewandelt. In der Dosis von 75 Mikrogramm täglich hemmt es – anders als ältere Minipillen – in den allermeisten Zyklen den Eisprung; zusätzlich verdickt es den Schleim am Gebärmutterhals. Da kein Östrogen enthalten ist, steigt das Thromboserisiko nach heutigem Wissen kaum.","nebenwirkungen":{"haeufig":["Unregelmässige Blutungen, Ausbleiben der Regel","Stimmungsschwankungen, depressive Verstimmung, verminderte Libido","Kopfschmerzen","Übelkeit","Akne","Brustschmerzen","Gewichtszunahme"],"gelegentlich":["Scheideninfektion","Unverträglichkeit von Kontaktlinsen","Erbrechen","Haarausfall","Schmerzhafte Regelblutung, Eierstockzysten","Müdigkeit"],"selten":["Hautausschlag, Nesselsucht","Erythema nodosum (entzündliche Hautknoten)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Angioödem","Absonderung aus der Brust"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft absetzen. Eine versehentliche Einnahme erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Erlaubt: Milchmenge und -qualität werden nicht beeinträchtigt; sehr geringe Mengen gehen in die Muttermilch über.","hinweise":["Täglich etwa zur gleichen Zeit ohne Pause einnehmen. Bei mehr als 12 Stunden Verspätung ist der Schutz vermindert: Tablette sofort nachnehmen und 7 Tage zusätzlich ein Kondom verwenden.","Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden nach der Einnahme gilt wie eine vergessene Tablette.","Unregelmässige Blutungen sind häufig, besonders in den ersten Monaten; anhaltende oder starke Blutungen ärztlich abklären.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"dexamethason":{"wirkmechanismus":"Dämpft Entzündungen, allergische Reaktionen und die Abwehrreaktionen des Immunsystems sehr stark. Dexamethason ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und die Ablesung zahlreicher Gene verändert: Entzündungsbotenstoffe wie Zytokine und Prostaglandine werden vermindert gebildet, Abwehrzellen gehemmt und durchlässige Gefässe abgedichtet. Es wirkt etwa 25- bis 30-mal stärker entzündungshemmend als körpereigenes Cortisol, hat praktisch keine salzzurückhaltende (mineralokortikoide) Wirkung und wirkt lange. Darum eignet es sich besonders bei Hirnödem und zur Vorbeugung von Übelkeit bei Chemotherapie.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Augeninnendruck und Bindehautblutung (Augenimplantat)"],"haeufig":["Katarakt (grauer Star), Augenschmerzen, Glaskörpertrübungen (Augenimplantat)","Augenbeschwerden wie Brennen und Stechen (Augentropfen)"],"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Dexamethason gelangt über die Plazenta zum Kind; bei längerer Behandlung sind Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in die Muttermilch über. Bei kurzer Anwendung meist vertretbar; bei höheren Dosen oder Langzeitbehandlung ärztlich abklären, ob abgestillt werden soll.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen (weniger Magenbeschwerden und Schlafstörungen).","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Augentropfen nur kurzzeitig und unter augenärztlicher Kontrolle anwenden; weiche Kontaktlinsen vorher herausnehmen."],"darreichung":["Tabletten","Injektionslösung","Augentropfen","Intravitreales Implantat (Augenimplantat)"]},"dexamethason-neomycin-polymyxin-b":{"wirkmechanismus":"Hemmt die Entzündung und bekämpft gleichzeitig Bakterien am Auge. Dexamethason ist ein stark wirksames Glukokortikoid, das die Bildung entzündungsfördernder Botenstoffe unterdrückt und Schwellung, Rötung und Juckreiz lindert. Neomycin ist ein Aminoglykosid-Antibiotikum, das die bakterielle Eiweisssynthese an den Ribosomen stört. Polymyxin B schädigt die Zellmembran gramnegativer Bakterien, einschliesslich Pseudomonas aeruginosa.","nebenwirkungen":{"gelegentlich":["Keratitis (Hornhautentzündung)","Erhöhter Augeninnendruck","Verschwommenes Sehen, Lichtempfindlichkeit","Pupillenerweiterung, hängendes Augenlid","Augenschmerzen, Augenschwellung, Juckreiz, Fremdkörpergefühl","Augenreizung, Augenrötung, vermehrter Tränenfluss"],"unbekannt":["Überempfindlichkeitsreaktionen, v. a. allergische Kontaktreaktion auf Neomycin","Kopfschmerzen","Hornhautgeschwür","Glaukom und Linsentrübung (Katarakt) bei längerer Anwendung","Pilz- oder Virusinfektionen des Auges (Sekundärinfektion)","Verzögerte Wundheilung"]},"schwangerschaft":"Keine ausreichenden Daten; Aminoglykoside können bei systemischer Gabe das Gehör des Ungeborenen schädigen. Nur bei klarer Notwendigkeit und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob die Wirkstoffe nach Anwendung am Auge in die Muttermilch gelangen; nur nach ärztlicher Abwägung.","hinweise":["Augentropfen vor Gebrauch gut schütteln.","Nicht länger als ärztlich verordnet anwenden; bei Anwendung über 10 Tage den Augeninnendruck kontrollieren lassen.","Während der Behandlung keine Kontaktlinsen tragen."],"darreichung":["Augentropfen (Suspension)","Augensalbe"]},"dexamfetamin":{"wirkmechanismus":"Steigert Aufmerksamkeit und Konzentration und dämpft Impulsivität, indem es die Botenstoffe Dopamin und Noradrenalin im Gehirn vermehrt. Dexamfetamin, die wirksamere rechtsdrehende Form von Amphetamin, hemmt die Wiederaufnahme dieser Botenstoffe und setzt sie zusätzlich aktiv aus den Nervenendigungen frei. Ausserhalb des Gehirns wirkt es sympathomimetisch: Puls und Blutdruck steigen.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Nervosität"],"haeufig":["Appetitminderung, verminderte Gewichts- und Grössenzunahme bei Kindern","Reizbarkeit, Aggressivität, Angst, Depression, abnormes Verhalten","Kopfschmerzen, Schwindel, Überaktivität, Dyskinesien (unwillkürliche Bewegungen)","Herzrasen, Herzklopfen, Herzrhythmusstörungen","Veränderungen von Blutdruck und Puls (meist Anstieg)","Bauchschmerzen, Übelkeit, Erbrechen, Mundtrockenheit","Gelenkschmerzen"],"selten":["Angina pectoris (Brustenge)","Hautausschlag, Nesselsucht","Müdigkeit","Wachstumsverzögerung bei Langzeitanwendung"],"sehrSelten":["Halluzinationen, Psychose, suizidales Verhalten","Tics oder Verschlechterung bestehender Tics","Krampfanfälle, Hirnblutung, zerebrale Vaskulitis","Herzstillstand","Leberfunktionsstörungen bis Leberkoma","Erythema multiforme, exfoliative Dermatitis","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)"],"unbekannt":["Abhängigkeit, Missbrauch","Kardiomyopathie, Herzinfarkt, plötzlicher Tod","Schlaganfall","Raynaud-Phänomen (kalte, weisse Finger)","Ischämische Kolitis (Darmdurchblutungsstörung)","Schwere Überempfindlichkeitsreaktionen (Angioödem, Anaphylaxie)","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Amphetamine können beim Neugeborenen zu Entzugssymptomen, Frühgeburt und niedrigem Geburtsgewicht führen.","stillzeit":"Dexamfetamin geht in die Muttermilch über; nicht stillen.","hinweise":["Untersteht dem Betäubungsmittelgesetz: sicher und für andere unzugänglich aufbewahren, nicht weitergeben.","Die letzte Dosis nicht zu spät am Tag einnehmen (Schlafstörungen).","Vor Beginn und regelmässig Puls, Blutdruck, Gewicht und bei Kindern die Körpergrösse kontrollieren; die Notwendigkeit der Behandlung periodisch überprüfen.","Alkohol meiden; die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Tabletten"]},"dexpanthenol":{"wirkmechanismus":"Fördert die Regeneration von Haut und Schleimhäuten. Dexpanthenol wird in der Haut rasch in Pantothensäure (Vitamin B5) umgewandelt, einen Baustein des Coenzyms A, das die Zellen für Stoffwechsel und Zellteilung brauchen. Es regt die Neubildung der obersten Hautschicht (Epithelisierung) an, verbessert die Feuchtigkeitsbindung der Haut und lindert Juckreiz leicht.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen","Kontaktdermatitis, Ekzem an der Auftragsstelle","Juckreiz, Rötung, Ausschlag oder Nesselsucht","Hautreizung, Bläschen"]},"schwangerschaft":"Kann angewendet werden; bei bestimmungsgemässer Anwendung sind keine Risiken bekannt.","stillzeit":"Kann angewendet werden, auch zur Pflege wunder Brustwarzen. Bepanthen Plus (mit Chlorhexidin) nicht auf die Brustwarzen auftragen.","hinweise":["Wunden, die sich nach einigen Tagen nicht bessern oder Entzündungszeichen zeigen (Rötung, Schwellung, Eiter, Fieber), ärztlich beurteilen lassen.","Bepanthen Plus enthält das Desinfektionsmittel Chlorhexidin: nicht zusammen mit Seifen oder anderen Desinfektionsmitteln auf derselben Stelle anwenden.","Augen- und Nasensalbe: nach dem Einbringen ins Auge kurzzeitig verschwommenes Sehen – erst wieder Auto fahren, wenn die Sicht klar ist."],"darreichung":["Salbe","Creme","Augen- und Nasensalbe"]},"dextromethorphan":{"wirkmechanismus":"Dämpft den Hustenreflex im Hirnstamm. Dextromethorphan ist ein Morphinan-Abkömmling ohne relevante Wirkung an μ-Opioidrezeptoren und deshalb ohne schmerzstillende Wirkung. Es wirkt am Sigma-1-Rezeptor, blockiert NMDA-Rezeptoren und hemmt die Wiederaufnahme von Serotonin. Abgebaut wird es vor allem über CYP2D6 zu Dextrorphan; bei langsamen Metabolisierern wirkt es stärker und länger.","nebenwirkungen":{"haeufig":["Müdigkeit, Benommenheit","Schwindel","Übelkeit, Erbrechen, Magen-Darm-Beschwerden"],"sehrSelten":["Halluzinationen","Abhängigkeit bei Missbrauch","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Angioödem, Bronchospasmus)"],"unbekannt":["Serotonin-Syndrom (Fieber, Unruhe, Muskelzuckungen, Durchfall), v. a. in Kombination mit serotonergen Mitteln","Bei Überdosierung: Verwirrtheit, Erregung, Sprach- und Bewegungsstörungen, Atemdämpfung"]},"schwangerschaft":"Im 1. Drittel nicht anwenden; danach nur kurzfristig nach ärztlicher Abwägung. Hohe Dosen kurz vor der Geburt können beim Neugeborenen die Atmung dämpfen.","stillzeit":"Nicht anwenden; der Übergang in die Muttermilch ist ungenügend untersucht und eine Atemdämpfung beim Säugling nicht auszuschliessen.","hinweise":["Nur bei trockenem Reizhusten und nur wenige Tage anwenden; bei Husten länger als 1–2 Wochen, Fieber oder Atemnot ärztlich abklären.","Vor der Einnahme in der Apotheke Antidepressiva und andere Dauermedikamente angeben (Serotonin-Syndrom).","Kein Alkohol; die Fahrtüchtigkeit kann beeinträchtigt sein.","Missbrauchsgefahr: hohe Dosen wirken berauschend und sind gefährlich – ausser Reichweite von Kindern und Jugendlichen aufbewahren."],"darreichung":["Sirup","Tabletten","Lösung zum Einnehmen (Kombipräparat)"]},"diazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend, muskelentspannend und krampflösend. Diazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt so die Wirkung des hemmenden Botenstoffs GABA (häufigere Öffnung des Chloridkanals). Es wird in der Leber v. a. über CYP2C19 und CYP3A4 zu ebenfalls wirksamen Abbauprodukten wie Desmethyldiazepam umgewandelt, das sehr lange im Körper bleibt; bei wiederholter Einnahme kann sich die Wirkung daher anhäufen.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit (Somnolenz)"],"haeufig":["Müdigkeit","Ataxie (Gangunsicherheit), gestörte Bewegungskoordination, Zittern","Verwirrtheit","Entzugserscheinungen beim Absetzen"],"gelegentlich":["Anterograde Amnesie (Gedächtnislücken)","Konzentrations- und Gleichgewichtsstörungen, Schwindel, Kopfschmerzen, verwaschene Sprache","Muskelschwäche","Übelkeit, Verstopfung, Durchfall","Allergische Hautreaktionen (Juckreiz, Rötung, Ausschlag)"],"selten":["Atemdepression bis Atemstillstand","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen)","Bradykardie, Blutdruckabfall, Ohnmacht","Harnverhalt, Inkontinenz","Libidoveränderungen"],"sehrSelten":["Leukopenie (Verminderung der weissen Blutkörperchen)","Erhöhte Leberwerte, Gelbsucht"],"unbekannt":["Körperliche und psychische Abhängigkeit","Stürze und Knochenbrüche, v. a. bei älteren Menschen","Venenreizung und Venenentzündung an der Injektionsstelle"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Bei Anwendung gegen Ende der Schwangerschaft oder während der Geburt können beim Neugeborenen Muskelschlaffheit, Atemprobleme, Unterkühlung und Entzugssymptome auftreten.","stillzeit":"Diazepam geht in die Muttermilch über und kann sich beim Säugling anreichern (Müdigkeit, Trinkschwäche). Nicht stillen.","hinweise":["So kurz wie möglich anwenden (bei Angst höchstens 8–12 Wochen einschliesslich Ausschleichen) – Gefahr von Gewöhnung und Abhängigkeit.","Nach längerer Einnahme nicht abrupt absetzen, sondern langsam ausschleichen (Entzugssymptome, Krampfanfälle).","Kein Alkohol; die Fahrtüchtigkeit kann auch noch am Folgetag beeinträchtigt sein.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Tabletten","Tropfen","Injektionslösung","Rektallösung (Rektaltuben)"]},"diclofenac":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung entzündungsfördernder Botenstoffe hemmt. Diclofenac hemmt reversibel die Cyclooxygenasen COX-1 und COX-2 (mit gewisser COX-2-Präferenz) und damit die Synthese von Prostaglandinen. Die Hemmung von COX-1 in Magenschleimhaut und Niere erklärt die typischen Magen-Darm- und Nierennebenwirkungen; die COX-2-Hemmung trägt zum erhöhten Herz-Kreislauf-Risiko bei.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Dyspepsie (Verdauungsbeschwerden), Blähungen, Appetitlosigkeit","Erhöhte Leberwerte (Transaminasen)","Hautausschlag","Gel und Pflaster: Rötung, Juckreiz oder Ekzem an der Auftragsstelle"],"gelegentlich":["Herzinfarkt, Herzinsuffizienz, Herzklopfen, Brustschmerzen (v. a. bei hoher Dosis und Langzeitanwendung)"],"selten":["Magen-Darm-Geschwüre und -Blutungen (Bluterbrechen, Teerstuhl)","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Asthmaanfälle","Hepatitis, Gelbsucht","Nesselsucht","Ödeme (Wassereinlagerungen)","Schläfrigkeit"],"sehrSelten":["Blutbildstörungen bis Agranulozytose (Ausfall der weissen Blutkörperchen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Fulminante Hepatitis, Leberversagen","Akutes Nierenversagen, nephrotisches Syndrom","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)","Sehstörungen, Ohrensausen (Tinnitus)","Bluthochdruck, Vaskulitis (Gefässentzündung)","Pankreatitis, Kolitis"],"unbekannt":["Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich (ab der 20. Woche Risiko für Nierenschäden beim Kind und Fruchtwassermangel). Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit möglichst meiden, eine kurze Anwendung nur nach ärztlicher Abwägung.","hinweise":["So niedrig dosiert und so kurz wie möglich anwenden; rezeptfreie Präparate ohne ärztlichen Rat nur wenige Tage einnehmen.","Tabletten unzerkaut mit Flüssigkeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","Gel nicht auf offene Wunden, Schleimhäute oder Augen auftragen und danach die Hände waschen.","Kann Schwindel und Müdigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Magensaftresistente Tabletten","Retardtabletten","Zäpfchen","Injektionslösung","Gel","Pflaster","Augentropfen"]},"dienogest":{"wirkmechanismus":"Lässt Endometriose-Herde schrumpfen, indem es eine dauerhafte Gestagenwirkung erzeugt und die Östrogenbildung dämpft. Dienogest bindet stark an Progesteronrezeptoren und wirkt an der Gebärmutterschleimhaut kräftig gestagen; zugleich hat es eine antiandrogene, aber keine androgene Wirkung. Bei täglicher Einnahme senkt es die Hormonausschüttung der Eierstöcke mässig, sodass ein östrogenarmes, gestagenbetontes Milieu entsteht. Das Gewebe der Endometrioseherde wird zunächst umgewandelt (Dezidualisierung) und bildet sich dann zurück.","nebenwirkungen":{"haeufig":["Uterine Blutungen, Schmierblutungen, verändertes Blutungsmuster","Kopfschmerzen, Migräne","Depressive Verstimmung, Stimmungsschwankungen, Schlafstörungen, Nervosität, Reizbarkeit","Libidoverlust","Brustbeschwerden","Gewichtszunahme","Übelkeit, Bauchschmerzen, Blähungen","Akne, Haarausfall","Hitzewallungen","Ovarialzysten (Eierstockzysten)","Rückenschmerzen, Schwäche"],"gelegentlich":["Anämie (Blutarmut)","Angst, Depression","Trockene Augen, Ohrensausen","Herzklopfen, tiefer Blutdruck","Atemnot","Durchfall, Verstopfung","Trockene Haut, Juckreiz, vermehrte Behaarung","Scheidenpilz, Harnwegsinfektionen","Wassereinlagerungen (Ödeme)"]},"schwangerschaft":"Nicht anwenden: Eine Endometriose muss in der Schwangerschaft nicht behandelt werden, und es gibt nur sehr wenige Daten.","stillzeit":"Nicht empfohlen – Dienogest geht in die Muttermilch über.","hinweise":["Täglich ohne Pause etwa zur gleichen Zeit einnehmen.","Visanne ist kein Verhütungsmittel: Falls Verhütung nötig ist, eine nichthormonale Methode (z. B. Kondom) verwenden.","Bei Erbrechen oder Durchfall innerhalb von 3–4 Stunden nach der Einnahme kann die Wirkung vermindert sein.","Unregelmässige Blutungen sind besonders in den ersten Monaten häufig; anhaltend starke Blutungen ärztlich abklären lassen."],"darreichung":["Tabletten"]},"digoxin":{"wirkmechanismus":"Verlangsamt einen zu schnellen Puls und verstärkt die Pumpkraft des Herzmuskels. Digoxin hemmt die Natrium-Kalium-Pumpe (Na+/K+-ATPase) der Herzmuskelzellen; dadurch steigt über den Natrium-Calcium-Austauscher die Calciumkonzentration in der Zelle, was die Kontraktionskraft erhöht (positiv inotrop). Zusätzlich verstärkt Digoxin den Einfluss des Vagusnervs und verlangsamt so die Überleitung im AV-Knoten, wodurch bei Vorhofflimmern weniger Impulse auf die Herzkammern übertragen werden. Die therapeutische Breite ist sehr eng; Digoxin wird überwiegend unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Durchfall","Schwindel und andere Störungen des Nervensystems","Sehstörungen (verschwommenes Sehen, Gelb- oder Grünsehen)","Herzrhythmusstörungen (z. B. Extraschläge, Bigeminus), Bradykardie (verlangsamter Herzschlag) und Leitungsstörungen","Hautausschlag (Nesselsucht-artig oder scharlachartig)"],"gelegentlich":["Depression"],"sehrSelten":["Thrombozytopenie (Mangel an Blutplättchen)","Appetitlosigkeit","Verwirrtheit, Apathie, Psychose","Kopfschmerzen","Gefährliche Herzrhythmusstörungen (Vorhof- und Kammertachykardien)","Durchblutungsstörung oder Absterben von Darmabschnitten (Darmischämie)","Gynäkomastie (Brustvergrösserung beim Mann) bei Langzeitbehandlung","Müdigkeit, Schwäche, Unwohlsein"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden, wenn es nötig ist; Digoxin gelangt zum Kind. Der Spiegel muss überwacht werden, da sich der Bedarf ändern kann.","stillzeit":"Geht nur in geringer Menge in die Muttermilch über; Stillen ist erlaubt.","hinweise":["Regelmässige Kontrollen von Digoxinspiegel, Kalium und Nierenfunktion sind wichtig.","Warnzeichen einer Überdosierung: Übelkeit, Appetitlosigkeit, Sehstörungen (Gelb- oder Grünsehen), Verwirrtheit, sehr langsamer oder unregelmässiger Puls – sofort ärztlich melden.","Antazida und Colestyramin mit mindestens 2 Stunden Abstand einnehmen; keine Johanniskraut-Präparate.","Jedes neue Medikament, auch Antibiotika, ärztlich auf Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten","Injektionslösung"]},"dihydralazin":{"wirkmechanismus":"Senkt den Blutdruck, indem es direkt die Muskulatur der kleinen Arterien (Arteriolen) entspannt. Der genaue Mechanismus ist nicht vollständig geklärt; Dihydralazin beeinflusst unter anderem die Calcium-Freisetzung in der glatten Gefässmuskulatur. Der periphere Widerstand sinkt; gegenregulatorisch steigen Herzfrequenz, Herzzeitvolumen und die Salz- und Wasserrückhaltung, weshalb es bei längerer Behandlung oft mit einem Betablocker und einem Diuretikum kombiniert wird.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Tachykardie (Herzrasen), Herzklopfen"],"haeufig":["Gesichtsrötung (Flush)","Hypotonie (Blutdruckabfall)","Angina-pectoris-ähnliche Beschwerden","Gelenk- und Muskelschmerzen, Gelenkschwellungen","Magen-Darm-Beschwerden (Übelkeit, Erbrechen, Durchfall)","Positive antinukleäre Antikörper (Laborbefund)"],"gelegentlich":["Lupus-ähnliches Syndrom (Gelenkschmerzen, Fieber, Hautausschlag)","Verstopfte Nase, tränende Augen","Ödeme (Wassereinlagerungen)","Schwindel"],"selten":["Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)","Hepatitis (Leberentzündung), Gelbsucht","Glomerulonephritis (Nierenentzündung)","Periphere Nervenentzündung (Kribbeln, Taubheit)"]},"schwangerschaft":"Wird zur Behandlung von schwerem Bluthochdruck in der Schwangerschaft eingesetzt (vor allem im 2. und 3. Drittel); im 1. Drittel nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Bei Gelenkschmerzen, Fieber, Hautausschlag oder Brustfellschmerzen ärztlich abklären lassen (Lupus-ähnliches Syndrom).","Bei der Injektion Blutdruck und Puls engmaschig überwachen; in der Schwangerschaft auch die Herztöne des Kindes.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen; Alkohol verstärkt die Wirkung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"diltiazem":{"wirkmechanismus":"Entlastet das Herz, senkt den Blutdruck und verlangsamt den Puls, indem es den Calcium-Einstrom in Herz- und Gefässmuskelzellen hemmt. Diltiazem blockiert L-Typ-Calciumkanäle: Es erweitert die Herzkranz- und peripheren Arterien, verhindert Gefässkrämpfe und senkt so den Sauerstoffbedarf des Herzens. Zusätzlich bremst es die Erregungsbildung im Sinusknoten und die Überleitung im AV-Knoten. Diltiazem wird über CYP3A4 abgebaut und hemmt dieses Enzym mässig.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (Wassereinlagerungen, vor allem an den Knöcheln)"],"haeufig":["Kopfschmerzen, Schwindel","AV-Block (verlangsamte Erregungsleitung im Herzen)","Herzklopfen","Flush (Gesichtsrötung mit Wärmegefühl)","Verstopfung, Verdauungsstörungen, Magenschmerzen, Übelkeit","Hautrötung (Erythem)","Unwohlsein, Müdigkeit"],"gelegentlich":["Bradykardie (langsamer Puls)","Blutdruckabfall beim Aufstehen","Nervosität, Schlaflosigkeit","Erbrechen, Durchfall","Erhöhte Leberwerte"],"selten":["Mundtrockenheit","Nesselsucht (Urtikaria)"],"unbekannt":["Sinusknotenstillstand, sinuatrialer Block, Herzstillstand, Verschlechterung einer Herzschwäche","Thrombozytopenie (Mangel an Blutplättchen)","Stimmungsschwankungen einschliesslich Depression; extrapyramidale Bewegungsstörungen","Hepatitis; Zahnfleischwucherung (Gingivahyperplasie)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, exfoliative Dermatitis)","Angioödem, Lichtempfindlichkeit, Vaskulitis (Gefässentzündung)","Brustvergrösserung beim Mann, vermehrtes Schwitzen"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Diltiazem geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Retardform unzerkaut mit Flüssigkeit schlucken.","Puls regelmässig messen; bei sehr langsamem Puls, Schwindel oder Ohnmacht ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn der Behandlung.","Vor Operationen und beim Beginn neuer Medikamente die Einnahme angeben – Diltiazem hat viele Wechselwirkungen."],"darreichung":["Tabletten bzw. Kapseln mit verzögerter Freisetzung (Retardform)"]},"dimenhydrinat":{"wirkmechanismus":"Dämpft das Gleichgewichtsorgan und das Brechzentrum im Gehirn und lindert so die Reiseübelkeit. Dimenhydrinat ist ein Salz aus Diphenhydramin und 8-Chlortheophyllin; wirksam ist das Diphenhydramin. Es blockiert zentrale und periphere Histamin-H1-Rezeptoren und wirkt zusätzlich anticholinerg (an Muskarinrezeptoren), wodurch die Weiterleitung von Signalen aus dem Gleichgewichtsorgan zum Brechzentrum gehemmt wird. Weil es gut ins Gehirn gelangt, macht es deutlich müde.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit und Benommenheit","Schwindelgefühl"],"unbekannt":["Mundtrockenheit","Sehstörungen und Anstieg des Augeninnendrucks","Verstopfung und Magen-Darm-Beschwerden","Erschwertes Wasserlassen bis Harnverhalt","Paradoxe Erregung, Unruhe und Schlafstörungen (v. a. bei Kindern)","Allergische Hautreaktionen und Lichtempfindlichkeit","Leberfunktionsstörungen (cholestatischer Ikterus)","Blutbildveränderungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Im letzten Schwangerschaftsdrittel nicht anwenden, da Dimenhydrinat vorzeitige Wehen auslösen kann.","stillzeit":"Geht in die Muttermilch über und kann beim Säugling Unruhe oder Schläfrigkeit verursachen – in der Stillzeit nicht empfohlen.","hinweise":["Zur Vorbeugung rechtzeitig vor Reisebeginn anwenden (Zeitpunkt gemäss Packungsbeilage).","Macht müde: keinen Alkohol trinken, nicht selbst Auto fahren und keine Maschinen bedienen.","Höchstdosis nicht überschreiten: Überdosierung kann Halluzinationen, Krampfanfälle und Herzrhythmusstörungen auslösen; Missbrauch ist möglich."],"darreichung":["Kaugummi","Tabletten (Kombipräparat)"]},"dimethylfumarat":{"wirkmechanismus":"Dämpft überschiessende Entzündungs- und Immunreaktionen. Dimethylfumarat wird im Darm rasch in Monomethylfumarat umgewandelt, den eigentlichen Wirkstoff. Dieser aktiviert den Nrf2-Signalweg, der Zellen vor oxidativem Stress schützt, hemmt entzündungsfördernde Signale (NF-kappaB) und verschiebt die Immunantwort von entzündlichen Th1- und Th17-Zellen hin zu Th2-Zellen. Zudem sinkt die Zahl der Lymphozyten im Blut.","nebenwirkungen":{"sehrHaeufig":["Flush (Hitzegefühl mit Hautrötung)","Durchfall, Übelkeit","Bauchschmerzen, Blähungen","Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen; vor allem unter Psoriasis-Therapie sehr häufig)"],"haeufig":["Erbrechen, Verdauungsbeschwerden, Magenschleimhautentzündung, Magen-Darm-Infekt","Juckreiz, Ausschlag, Hautrötung, Brennen der Haut","Kopfschmerzen, Kribbeln (Parästhesien)","Erhöhte Leberwerte","Eiweiss und Ketone im Urin (Proteinurie, Ketonurie)","Müdigkeit, Schwäche, Hitzegefühl","Eosinophilie (Anstieg bestimmter weisser Blutkörperchen)","Appetitminderung"],"gelegentlich":["Überempfindlichkeitsreaktionen","Thrombozytopenie (Mangel an Blutplättchen)","Schwindel","Erhöhtes Kreatinin im Blut"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Gürtelrose (Herpes zoster) und andere opportunistische Infektionen","Anaphylaxie, Angioödem, Atemnot","Arzneimittelbedingte Leberschädigung","Fanconi-Syndrom (Nierenschaden)","Laufende Nase"]},"schwangerschaft":"Multiple Sklerose: nur nach sorgfältiger ärztlicher Abwägung, wenn klar notwendig. Psoriasis-Präparat (Skilarence): kontraindiziert, Frauen im gebärfähigen Alter müssen sicher verhüten.","stillzeit":"Unklar, ob der Wirkstoff in die Muttermilch übergeht: bei MS nur nach ärztlicher Abwägung; das Psoriasis-Präparat ist in der Stillzeit kontraindiziert.","hinweise":["Mit einer Mahlzeit einnehmen und unzerkaut schlucken – das mildert Flush und Magen-Darm-Beschwerden; die Dosis wird zu Beginn langsam gesteigert.","Blutbild (Lymphozyten) vor Beginn und regelmässig, mindestens alle 3 Monate, sowie Leber- und Nierenwerte und Urin kontrollieren lassen.","Neue oder zunehmende neurologische Beschwerden (Schwäche, Seh-, Sprach- oder Gedächtnisstörungen) sofort melden.","Keine hochprozentigen alkoholischen Getränke innerhalb einer Stunde nach der Einnahme."],"darreichung":["Magensaftresistente Hartkapseln (Multiple Sklerose)","Magensaftresistente Tabletten (Psoriasis)"]},"dimetinden":{"wirkmechanismus":"Lindert Juckreiz und allergische Beschwerden, indem es den Botenstoff Histamin blockiert. Dimetinden ist ein Antagonist am Histamin-H1-Rezeptor und vermindert so Gefässdurchlässigkeit, Quaddelbildung, Rötung und Juckreiz. Auf der Haut wirkt es zusätzlich leicht örtlich betäubend, weshalb das Gel Juckreiz rasch lindert. Eingenommen gelangt es ins Gehirn und macht deshalb müde; zudem hat es schwache anticholinerge Wirkungen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit (Tropfen)"],"haeufig":["Schläfrigkeit, Benommenheit (Tropfen)","Nervosität (Tropfen)"],"selten":["Unruhe, Erregung","Kopfschmerzen, Schwindel","Übelkeit, Magen-Darm-Beschwerden","Mund- und Rachentrockenheit"],"sehrSelten":["Anaphylaktische Reaktionen mit Schwellung von Gesicht und Rachen","Hautausschlag","Muskelkrämpfe","Atembeschwerden"],"unbekannt":["Trockene Haut und Brennen an der Auftragsstelle (Gel)","Allergische Hautreaktionen (Gel)","Brennen und Trockenheit der Nasenschleimhaut (Vibrocil)"]},"schwangerschaft":"Tropfen nur nach ärztlicher Abwägung, besonders im 1. Drittel zurückhaltend. Gel kleinflächig nach Abwägung möglich, nicht auf grosse, entzündete oder verletzte Hautflächen.","stillzeit":"Tropfen nicht empfohlen (Übergang in die Muttermilch, Müdigkeit beim Säugling möglich). Gel nicht auf die Brust auftragen.","hinweise":["Die Tropfen machen müde: Fahrtüchtigkeit und Reaktionsvermögen können eingeschränkt sein, besonders zusammen mit Alkohol.","Gel: bei grossflächiger Anwendung behandelte Haut nicht der Sonne aussetzen; bei Juckreiz, der nach einigen Tagen nicht bessert oder grosse Flächen betrifft, Arzt aufsuchen.","Vibrocil (mit Phenylephrin) ohne ärztlichen Rat nicht länger als 7 Tage anwenden – sonst droht eine dauerhaft verstopfte Nase."],"darreichung":["Tropfen zum Einnehmen","Gel","Roll-on","Nasenspray, Nasentropfen, Nasengel (Kombi mit Phenylephrin)"]},"diosmectit":{"wirkmechanismus":"Bindet im Darm überschüssiges Wasser sowie Krankheitserreger und deren Giftstoffe und schützt die Darmschleimhaut. Diosmectit ist ein natürliches Tonmineral (Aluminium-Magnesium-Silikat) mit blättchenartiger Struktur und sehr grosser Oberfläche. Es legt sich als Schutzfilm über die Schleimhaut, wird weder aufgenommen noch verstoffwechselt und unverändert mit dem Stuhl ausgeschieden.","nebenwirkungen":{"haeufig":["Verstopfung"],"unbekannt":["Blähungen","Erbrechen","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Juckreiz, Angioödem)"]},"schwangerschaft":"Nur kurzfristig und nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Nur kurzfristig und nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","hinweise":["Pulver in Wasser einrühren und gleich trinken.","Mindestens 2 Stunden Abstand zu anderen Medikamenten einhalten.","Bei Durchfall viel trinken; bei Kindern und älteren Menschen Elektrolytlösungen zur Rehydratation verwenden.","Hält der Durchfall länger als 2 Tage an oder treten Fieber oder Blut im Stuhl auf, ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Suspension zum Einnehmen (Beutel)"]},"diosmin":{"wirkmechanismus":"Stärkt die Venenwände und verringert Schwellungen in den Beinen. Die mikronisierte Flavonoidfraktion (90 % Diosmin, 10 % weitere Flavonoide, ausgedrückt als Hesperidin) erhöht die Spannung der Venenwand, indem sie die Wirkung von Noradrenalin an der Venenwand verlängert. Zudem vermindert sie die Durchlässigkeit und Brüchigkeit der kleinsten Blutgefässe (Kapillaren), hemmt das Anhaften weisser Blutkörperchen an der Gefässwand und die damit verbundene Entzündung und fördert den Lymphabfluss. Die Mikronisierung verbessert die Aufnahme aus dem Darm.","nebenwirkungen":{"haeufig":["Durchfall","Dyspepsie (Verdauungsbeschwerden)","Übelkeit, Erbrechen"],"gelegentlich":["Kolitis (Dickdarmentzündung)"],"selten":["Schwindel, Kopfschmerzen, Unwohlsein","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Bauchschmerzen","Schwellung von Gesicht, Lippen oder Augenlidern, ausnahmsweise Angioödem (Quincke-Ödem)"]},"schwangerschaft":"Im Tierversuch keine schädlichen Wirkungen, beim Menschen nur begrenzte Erfahrungen; vorsichtshalber in der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Zu den Mahlzeiten einnehmen.","Wirkt am besten zusammen mit Kompressionsstrümpfen, regelmässiger Bewegung, Hochlagern der Beine und Meiden von Hitze und langem Stehen.","Bei Hämorrhoidalattacken nur kurzfristig in der höheren Dosierung einnehmen; ohne rasche Besserung ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"diphtherie-tetanus-impfstoff-td":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen die Gifte der Tetanus- und Diphtherie-Bakterien zu bilden. Der Impfstoff enthält diese Gifte in unschädlich gemachter Form (Toxoide), gebunden an ein Aluminiumsalz zur Verstärkung der Immunantwort. Die Diphtherie-Komponente ist für ältere Kinder und Erwachsene reduziert («d»), um Lokalreaktionen zu vermindern. Der Impfstoff enthält keine Keuchhusten-Komponente.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung an der Einstichstelle"],"haeufig":["Verhärtung oder Knötchen an der Einstichstelle","Kopfschmerzen","Müdigkeit, Unwohlsein","Muskelschmerzen"],"gelegentlich":["Fieber","Schwindel","Übelkeit, Erbrechen","Geschwollene Lymphknoten","Gelenkschmerzen"],"unbekannt":["Allergische Reaktionen bis zur Anaphylaxie","Guillain-Barré-Syndrom, Brachialneuritis (Nervenentzündung des Armgeflechts)","Steriler Abszess an der Einstichstelle"]},"schwangerschaft":"Impfung ist möglich, wenn angezeigt (z. B. Tetanusschutz nach Verletzung); in der Schwangerschaft wird in der Regel dTpa mit Keuchhustenschutz bevorzugt.","stillzeit":"Impfung in der Stillzeit möglich.","hinweise":["Auffrischungen gemäss Schweizerischem Impfplan (Erwachsene in der Regel mit 25, 45 und 65 Jahren, danach alle 10 Jahre).","Bei Verletzungen den Impfausweis vorlegen – je nach letzter Impfung ist eine Auffrischung und evtl. Tetanus-Immunglobulin nötig.","Wo auch Keuchhustenschutz sinnvoll ist, wird meist ein dTpa-Impfstoff verwendet."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"diphtherie-tetanus-pertussis-impfstoff-dtpa":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen Diphtherie, Tetanus und Keuchhusten zu bilden. Der Impfstoff enthält unschädlich gemachte Bakteriengifte (Toxoide) von Diphtherie und Tetanus sowie gereinigte Bestandteile des Keuchhustenerregers (azelluläre Pertussis-Antigene) in reduzierter Menge, die für Auffrischimpfungen ausreicht. Bei Impfung in der Schwangerschaft gehen die mütterlichen Antikörper über die Plazenta auf das Kind über und schützen es in den ersten Lebensmonaten.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung an der Einstichstelle","Kopfschmerzen","Müdigkeit","Kinder: Reizbarkeit, Schläfrigkeit"],"haeufig":["Fieber","Schwindel","Übelkeit, Magen-Darm-Beschwerden, Appetitlosigkeit","Verhärtung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Fieber über 39 °C","Ausgedehnte Schwellung des geimpften Arms","Geschwollene Lymphknoten","Gelenk- und Muskelschmerzen","Halsschmerzen, Husten","Juckreiz, Hautausschlag"],"unbekannt":["Allergische Reaktionen bis zur Anaphylaxie","Krampfanfälle","Kollaps oder schockähnlicher Zustand mit verminderter Ansprechbarkeit (bei Kindern)","Nesselsucht, Angioödem","Guillain-Barré-Syndrom und Nervenentzündung des Armgeflechts (Brachialneuritis)"]},"schwangerschaft":"Empfohlen in jeder Schwangerschaft, idealerweise im 2. Drittel (gemäss Schweizerischem Impfplan); schützt das Neugeborene vor Keuchhusten.","stillzeit":"Impfung in der Stillzeit möglich.","hinweise":["Auffrischung gemäss Schweizerischem Impfplan; Personen mit Kontakt zu Säuglingen sollten gegen Keuchhusten geschützt sein.","Für die Grundimmunisierung von Säuglingen nicht geeignet (dafür gibt es Kinderimpfstoffe).","Nach der Impfung etwa 15 Minuten in der Praxis bleiben."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"diphtherie-tetanus-pertussis-poliomyelitis-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen vier Krankheiten zu bilden. Der Impfstoff enthält unschädlich gemachte Bakteriengifte (Toxoide) von Diphtherie und Tetanus, gereinigte Bestandteile des Keuchhustenbakteriums (azelluläre Pertussis-Antigene) sowie abgetötete Polioviren der Typen 1, 2 und 3, gebunden an Aluminiumsalze. Die gebildeten Antikörper neutralisieren die Bakteriengifte bzw. die Polioviren. Präparate mit kleinem «d» und «p» enthalten weniger Diphtherie- und Pertussis-Antigen und sind für die Auffrischung ab dem Schulalter bestimmt.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung und Schwellung an der Einstichstelle","Müdigkeit, Kopfschmerzen","Reizbarkeit und Schläfrigkeit (bei Kindern)"],"haeufig":["Fieber","Appetitlosigkeit","Übelkeit, Erbrechen, Durchfall","Verhärtung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Lymphknotenschwellung","Muskel- und Gelenkschmerzen","Schwindel"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Ausgedehnte Schwellung der geimpften Gliedmasse","Krampfanfälle mit oder ohne Fieber","Kollapsähnliche Zustände bei Kindern (hypoton-hyporesponsive Episode)","Nesselsucht"]},"schwangerschaft":"Die Keuchhustenimpfung wird in der Schweiz in jeder Schwangerschaft empfohlen, idealerweise im 2. Drittel (13.–26. Woche); die mütterlichen Antikörper schützen das Neugeborene. Bisherige Daten zeigen kein Risiko für das Kind.","stillzeit":"Impfung während der Stillzeit möglich.","hinweise":["Erwachsene: Auffrischung gegen Diphtherie und Tetanus in der Schweiz mit 25, 45 und 65 Jahren, danach alle 10 Jahre; Keuchhustenschutz besonders bei Kontakt mit Säuglingen.","Bei Verletzungen kann je nach Impfstatus eine vorzeitige Tetanus-Auffrischung nötig sein – Impfausweis mitbringen.","Fieber und Schmerzen an der Einstichstelle in den ersten 1–2 Tagen sind häufig und harmlos."],"darreichung":["Injektionssuspension in Fertigspritze"]},"dipyridamol":{"wirkmechanismus":"Macht die Blutplättchen weniger klebrig und erweitert die Blutgefässe. Dipyridamol hemmt die Wiederaufnahme von Adenosin in rote Blutkörperchen, Blutplättchen und Gefässwandzellen, sodass mehr Adenosin an seinen Rezeptoren wirkt. Zusätzlich hemmt es Phosphodiesterasen in den Blutplättchen; beides erhöht dort cAMP bzw. cGMP und vermindert die Plättchenverklumpung. Zusammen mit ASS, die über einen anderen Weg (Cyclooxygenase) wirkt, wird die Plättchenhemmung verstärkt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (v. a. zu Beginn)","Schwindel","Übelkeit, Durchfall","Bauchschmerzen, Verdauungsbeschwerden"],"haeufig":["Erbrechen","Muskelschmerzen","Verstärkung von Angina-pectoris-Beschwerden","Blutungen, z. B. Nasenbluten oder Magen-Darm-Blutungen (in Kombination mit ASS)"],"unbekannt":["Herzrasen (Tachykardie), Blutdruckabfall, Hitzegefühl","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Bronchospasmus, Angioödem)","Hirnblutung (in Kombination mit ASS)","Einlagerung von Dipyridamol in Gallensteine","Verstärkte Blutungen während oder nach Operationen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Das Kombipräparat mit ASS ist im letzten Schwangerschaftsdrittel kontraindiziert.","stillzeit":"Dipyridamol geht in geringen Mengen in die Muttermilch über; Anwendung nur, wenn klar notwendig.","hinweise":["Kopfschmerzen sind zu Beginn häufig und lassen meist nach einigen Tagen nach; Kapseln ganz schlucken.","Beim Kombipräparat mit ASS gelten zusätzlich alle Gegenanzeigen der Acetylsalicylsäure (z. B. aktive Magengeschwüre, Blutungsneigung, Analgetika-Asthma).","Vor Operationen, Zahnbehandlungen oder einem Herz-Stresstest die Einnahme angeben."],"darreichung":["Retardkapseln (Kombination mit Acetylsalicylsäure)"]},"dobutamin":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens. Dobutamin ist ein synthetisches Katecholamin, das vorwiegend die Beta-1-Rezeptoren des Herzmuskels stimuliert und so Schlagkraft und Herzzeitvolumen erhöht. Herzfrequenz und Blutdruck steigen meist nur mässig, weil sich schwache gefässerweiternde (Beta-2) und gefässverengende (Alpha-1) Effekte weitgehend aufheben. Anders als Dopamin setzt es kein Noradrenalin frei; die Wirkung klingt wenige Minuten nach Infusionsende ab.","nebenwirkungen":{"unbekannt":["Herzrasen (Tachykardie), Extrasystolen, Herzklopfen","Herzrhythmusstörungen bis Kammertachykardie oder Kammerflimmern","Blutdruckanstieg, seltener Blutdruckabfall","Brustschmerzen (Angina pectoris)","Kopfschmerzen, Übelkeit","Atemnot","Hypokaliämie (Kaliummangel)","Venenentzündung an der Infusionsstelle"]},"schwangerschaft":"Keine ausreichenden Daten; nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Nicht bekannt, ob Dobutamin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital als Dauerinfusion mit Infusionspumpe unter laufender Überwachung von EKG, Blutdruck und Puls gegeben.","Nicht mit alkalischen Lösungen (z. B. Natriumhydrogencarbonat) in derselben Leitung mischen."],"darreichung":["Infusionskonzentrat bzw. Infusionslösung"]},"docetaxel":{"wirkmechanismus":"Hemmt die Zellteilung, indem es das Zellskelett der Krebszellen erstarren lässt. Docetaxel fördert den Zusammenbau von Tubulin zu Mikrotubuli und hemmt deren Abbau; mit den starren Mikrotubuli kann keine funktionsfähige Mitosespindel entstehen. Die Zellen werden in der Mitose blockiert und sterben ab. Docetaxel wird in der Leber hauptsächlich über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Anämie, febrile Neutropenie, Infektionen","Überempfindlichkeitsreaktionen","Periphere sensorische Neuropathie (Kribbeln, Taubheit), Geschmacksstörungen","Atemnot","Stomatitis, Durchfall, Übelkeit, Erbrechen, Appetitlosigkeit","Haarausfall, Hautreaktionen, Nagelveränderungen","Flüssigkeitseinlagerung (Ödeme)","Muskelschmerzen, Schwäche (Asthenie), Schmerzen"],"haeufig":["Thrombozytopenie, Blutungen","Motorische Neuropathie (Muskelschwäche)","Herzrhythmusstörungen","Blutdruckabfall oder -anstieg","Verstopfung, Bauchschmerzen, Magen-Darm-Blutungen","Gelenkschmerzen","Erhöhte Leberwerte und Bilirubin","Reaktionen an der Infusionsstelle"],"gelegentlich":["Herzschwäche","Ösophagitis (Speiseröhrenentzündung)"],"unbekannt":["Interstitielle Lungenerkrankung, Pneumonitis, Lungenfibrose","Neutropenische Enterokolitis, ischämische Kolitis, Darmperforation","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Sklerodermie-artige Hautveränderungen","Zystoides Makulaödem (Sehstörung), vermehrter Tränenfluss","Hyponatriämie (Natriummangel)","Akute myeloische Leukämie, myelodysplastisches Syndrom (Zweiterkrankung)","Strahlen-Recall-Reaktionen","Tumorlyse-Syndrom"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – Stillen während der Behandlung unterbrechen.","hinweise":["Vor jeder Infusion wird ein Kortikosteroid (z. B. Dexamethason) eingenommen, um Flüssigkeitseinlagerungen und Überempfindlichkeitsreaktionen zu vermindern.","Die Infusionslösung enthält Alkohol: nach der Infusion Fahrtüchtigkeit beachten.","Blutbild vor jedem Zyklus; bei Fieber, Bauchschmerzen oder Durchfall sofort ärztliche Hilfe holen.","Gewichtszunahme, Schwellungen oder Atemnot melden (Flüssigkeitseinlagerung)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"dolutegravir":{"wirkmechanismus":"Verhindert, dass HIV sein Erbgut in die menschlichen Zellen einbaut. Dolutegravir bindet an das aktive Zentrum der viralen Integrase und blockiert den Strangtransfer, mit dem die virale DNA in die DNA der Wirtszelle eingefügt wird; ohne diesen Schritt kann sich das Virus nicht vermehren. Dolutegravir hat eine hohe Resistenzbarriere. Es hemmt zudem den Nierentransporter OCT2, was den Kreatininwert leicht erhöht, ohne die Nierenfunktion zu verschlechtern.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall"],"haeufig":["Schlaflosigkeit, abnorme Träume","Depression, Angst","Schwindel, Schläfrigkeit","Erbrechen, Blähungen, Bauchschmerzen","Hautausschlag, Juckreiz","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK)","Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen (Ausschlag, Fieber, Organbeteiligung)","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch (vor allem bei Depression in der Vorgeschichte)","Panikattacken","Gelenk- und Muskelschmerzen","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Erhöhtes Bilirubin","Suizid (bei psychischer Vorerkrankung)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit in der Schwangerschaft angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte bei Einnahme zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dolutegravir 2 Stunden davor oder 6 Stunden danach).","Bei Hautausschlag mit Fieber, Blasen, Gelenkschmerzen oder Gelbsucht sofort ärztlich melden.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"dolutegravir-lamivudin":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Dolutegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Lamivudin, ein Cytidin-Analogon, wird in den Zellen zum Triphosphat aktiviert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führt zum Kettenabbruch. Dank der hohen Resistenzbarriere von Dolutegravir genügen bei geeigneten Personen zwei Wirkstoffe.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schläfrigkeit","Übelkeit, Durchfall, Erbrechen, Blähungen, Bauchschmerzen","Schlaflosigkeit, abnorme Träume","Depression, Angst","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit","Erhöhte Leberwerte und Kreatinkinase (CK), Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen","Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch, Panikattacken (vor allem bei psychischer Vorerkrankung)","Neutropenie, Anämie, Thrombozytopenie","Immunrekonstitutionssyndrom"],"selten":["Akutes Leberversagen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Rhabdomyolyse (Muskelzerfall)","Angioödem (Schwellung von Haut und Schleimhäuten)","Laktatazidose (Übersäuerung des Blutes)","Suizid (bei psychischer Vorerkrankung)"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte durch Dolutegravir zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Antazida, Magnesium-, Eisen-, Calcium- oder Zinkpräparate und Multivitamine nur zeitversetzt (Dovato 2 Stunden davor oder 6 Stunden danach).","Vor Beginn auf Hepatitis B testen; bei Hepatitis B nicht eigenmächtig absetzen.","Ein leicht erhöhter Kreatininwert zu Beginn ist meist harmlos (Hemmung eines Nierentransporters)."],"darreichung":["Filmtabletten"]},"domperidon":{"wirkmechanismus":"Wirkt gegen Übelkeit und beschleunigt die Weitergabe des Mageninhalts in den Darm. Domperidon blockiert Dopamin-D2-Rezeptoren in der Brechreizzone (Chemorezeptor-Triggerzone), die ausserhalb der Blut-Hirn-Schranke liegt, sowie im Magen. Dadurch steigen Magenbeweglichkeit und Druck des unteren Speiseröhren-Schliessmuskels. Da es kaum ins Gehirn gelangt, sind Bewegungsstörungen seltener als bei Metoclopramid; über die Hypophyse kann es jedoch das Prolaktin erhöhen. In höheren Spiegeln hemmt es Kaliumkanäle im Herzen (hERG) und verlängert die QT-Zeit.","nebenwirkungen":{"haeufig":["Mundtrockenheit"],"gelegentlich":["Kopfschmerzen, Schläfrigkeit","Angst, Libidoverlust","Durchfall","Hautausschlag, Juckreiz","Milchfluss aus der Brust (Galaktorrhö), Brustschmerzen und -spannen","Schwächegefühl (Asthenie)"],"unbekannt":["Ventrikuläre Herzrhythmusstörungen, QT-Verlängerung, Torsade de pointes, plötzlicher Herztod","Krampfanfälle, extrapyramidale Bewegungsstörungen, Blickkrämpfe","Unruhe, Nervosität","Anaphylaxie, Angioödem, Nesselsucht","Brustvergrösserung beim Mann (Gynäkomastie), Ausbleiben der Regelblutung","Harnverhalt","Erhöhte Leberwerte und erhöhtes Prolaktin im Blut"]},"schwangerschaft":"Nur begrenzte Erfahrungen; in der Schwangerschaft nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; ein Risiko für Herznebenwirkungen beim Säugling ist nicht ausgeschlossen. Nur nach ärztlicher Abwägung.","hinweise":["Höchstdosis 30 mg pro Tag (meist 3 × 10 mg); in der Regel nicht länger als eine Woche anwenden.","Vor den Mahlzeiten einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Alle anderen Medikamente angeben – viele erhöhen zusammen mit Domperidon das Risiko für Herzrhythmusstörungen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Schmelztabletten"]},"donepezil":{"wirkmechanismus":"Verbessert bei Alzheimer-Demenz vorübergehend Gedächtnis und Alltagsfähigkeiten, indem es den Abbau des Botenstoffs Acetylcholin im Gehirn bremst. Donepezil hemmt spezifisch und reversibel die Acetylcholinesterase und erhöht so die Acetylcholin-Konzentration an den Synapsen der noch funktionierenden Nervenzellen. Den Verlauf der Erkrankung hält es nicht auf. Es wird über CYP3A4 und CYP2D6 abgebaut und hat eine sehr lange Halbwertszeit (etwa 70 Stunden).","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Kopfschmerzen"],"haeufig":["Appetitlosigkeit","Erbrechen, Bauchbeschwerden","Halluzinationen, Unruhe, Aggressivität, abnorme Träume","Schwindel, Schlaflosigkeit, Ohnmacht (Synkope)","Muskelkrämpfe","Harninkontinenz","Müdigkeit, Schmerzen, Stürze","Hautausschlag, Juckreiz, Erkältung"],"gelegentlich":["Bradykardie (langsamer Puls)","Krampfanfälle","Magen-Darm-Blutungen, Magen- und Zwölffingerdarmgeschwüre","Vermehrter Speichelfluss","Leichter Anstieg der Kreatinkinase (CK)"],"selten":["Sinuatrialer Block, AV-Block (Reizleitungsstörungen)","Extrapyramidale Symptome (Bewegungsstörungen)","Leberfunktionsstörungen, Hepatitis"],"sehrSelten":["Malignes neuroleptisches Syndrom","Rhabdomyolyse (Muskelzerfall)"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Pisa-Syndrom (seitliche Rumpfneigung)","Gesteigerte Libido, Hypersexualität"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Donepezil in die Muttermilch übergeht; nicht stillen.","hinweise":["Abends vor dem Schlafengehen einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Vor einer Narkose die Einnahme angeben.","Bei Schwindel, Ohnmacht oder sehr langsamem Puls ärztlich abklären lassen.","Die Fahrtüchtigkeit kann durch die Demenz und durch Nebenwirkungen eingeschränkt sein."],"darreichung":["Filmtabletten","Schmelztabletten"]},"dopamin":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens und erhöht je nach Dosis den Blutdruck. Dopamin ist ein körpereigenes Katecholamin und die Vorstufe von Noradrenalin. In niedriger Dosis stimuliert es vor allem Dopamin-D1-Rezeptoren (Gefässerweiterung in Niere und Bauchorganen), in mittlerer Dosis Beta-1-Rezeptoren des Herzens (mehr Schlagkraft und Herzfrequenz) und in hoher Dosis Alpha-1-Rezeptoren (Gefässverengung, Blutdruckanstieg). Zusätzlich setzt es Noradrenalin aus Nervenendigungen frei.","nebenwirkungen":{"unbekannt":["Herzrasen (Tachykardie), Extrasystolen, Herzklopfen","Herzrhythmusstörungen bis Kammertachykardie","Brustschmerzen (Angina pectoris)","Blutdruckanstieg oder Blutdruckabfall","Kopfschmerzen, Übelkeit, Erbrechen","Atemnot (Dyspnoe)","Gefässverengung mit kalten Fingern und Zehen bis Gewebsuntergang (Gangrän)","Gewebsnekrose bei Austritt der Infusion ins Gewebe"]},"schwangerschaft":"Keine ausreichenden Daten; nur bei lebensbedrohlichen Zuständen nach sorgfältiger Abwägung (mögliche Minderdurchblutung der Gebärmutter).","stillzeit":"Nicht bekannt, ob Dopamin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital (Intensivstation, Notfall, Anästhesie) als Dauerinfusion mit Infusionspumpe unter laufender Überwachung von Blutdruck, Puls und EKG gegeben.","Nicht abrupt beenden, sondern schrittweise reduzieren (Gefahr eines Blutdruckabfalls).","Schmerzen, Blässe oder Schwellung an der Infusionsstelle sofort dem Pflegepersonal melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"dorzolamid":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Dorzolamid hemmt das Enzym Carboanhydrase II im Ziliarkörper des Auges; dadurch entsteht weniger Bicarbonat, und der damit verbundene Natrium- und Flüssigkeitstransport ins Auge nimmt ab. Als Augentropfen wirkt es vor allem am Auge, während die Wirkung auf den übrigen Körper gering bleibt. Chemisch ist Dorzolamid ein Sulfonamid.","nebenwirkungen":{"sehrHaeufig":["Brennen und Stechen am Auge"],"haeufig":["Oberflächliche Hornhautentzündung (Keratitis punctata)","Tränenfluss, Bindehautentzündung, Lidentzündung, Augenjucken","Verschwommenes Sehen","Bitterer Geschmack","Kopfschmerzen, Übelkeit, Müdigkeit"],"gelegentlich":["Entzündung von Regenbogenhaut und Ziliarkörper (Iridozyklitis)"],"selten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Bronchospasmus)","Schwindel, Kribbeln (Parästhesien)","Augenrötung, Augenschmerzen, Lidkrusten, vorübergehende Kurzsichtigkeit","Hornhautschwellung, Aderhautabhebung nach Glaukomoperation","Nasenbluten, Rachenreizung, Mundtrockenheit","Nierensteine","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"],"unbekannt":["Fremdkörpergefühl im Auge"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Dorzolamid in die Muttermilch übergeht; ist die Behandlung nötig, wird das Stillen nicht empfohlen.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen oder den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei mehreren Augentropfen mindestens 10 Minuten Abstand halten.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen."],"darreichung":["Augentropfen"]},"dorzolamid-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem die Bildung von Kammerwasser auf zwei Wegen gedrosselt wird. Dorzolamid hemmt die Carboanhydrase II im Ziliarkörper und vermindert so die Bicarbonat- und Flüssigkeitsbildung. Timolol, ein nicht selektiver Betablocker, verringert die Kammerwasserproduktion zusätzlich. Ein Teil beider Wirkstoffe gelangt in den Kreislauf; vor allem Timolol kann Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Brennen und Stechen am Auge","Geschmacksstörung (bitterer Geschmack)"],"haeufig":["Augenrötung, Augenjucken, Tränenfluss","Verschwommenes Sehen","Hornhauterosion, oberflächliche Hornhautentzündung","Bindehaut- und Lidentzündung, Lidreizung","Kopfschmerzen, Übelkeit, Müdigkeit","Nasennebenhöhlenentzündung (Sinusitis)"],"gelegentlich":["Entzündung von Regenbogenhaut und Ziliarkörper (Iridozyklitis)","Schwindel"],"selten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Bronchospasmus)","Aderhautabhebung nach Glaukomoperation, Doppelbilder, hängendes Augenlid","Kribbeln (Parästhesien), Schlaflosigkeit, Albträume","Nierensteine","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (sehr schwere Hautreaktionen)"],"unbekannt":["Langsamer Puls (Bradykardie), AV-Block, Herzinsuffizienz, Blutdruckabfall","Verdeckte Unterzuckerung"]},"schwangerschaft":"In der Schwangerschaft nicht anwenden (Dorzolamid im Tierversuch fruchtschädigend; Timolol kann beim Neugeborenen Puls und Blutzucker senken).","stillzeit":"Nicht anwenden; ist die Behandlung nötig, wird abgestillt.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 10 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"doxazosin":{"wirkmechanismus":"Entspannt die Muskulatur in den Blutgefässen sowie in Prostata und Blasenhals. Doxazosin blockiert selektiv und kompetitiv Alpha-1-Rezeptoren, über die Noradrenalin normalerweise die glatte Muskulatur zusammenzieht. In den Gefässen sinkt dadurch der Widerstand und damit der Blutdruck; in Prostata und Blasenhals lässt der Druck auf die Harnröhre nach, sodass der Urin leichter abfliesst. Die erste Dosis kann einen deutlichen Blutdruckabfall auslösen (First-Dose-Effekt).","nebenwirkungen":{"haeufig":["Schwindel, Drehschwindel, Kopfschmerzen, Schläfrigkeit","Blutdruckabfall, auch beim Aufstehen (orthostatische Hypotonie)","Herzklopfen, Herzrasen","Atemwegsinfekte, Schnupfen, Husten, Atemnot","Bauchschmerzen, Verdauungsbeschwerden, Übelkeit, Mundtrockenheit","Harnwegsinfekt, Blasenentzündung, Harninkontinenz","Schwäche, grippeähnliche Beschwerden, Brustschmerzen, Wassereinlagerungen in den Beinen","Rücken- und Muskelschmerzen, Juckreiz"],"gelegentlich":["Ohnmacht (Synkope), Zittern","Angina pectoris, Herzinfarkt","Schlaganfall","Angst, Depression, Schlaflosigkeit","Verstopfung, Durchfall, Erbrechen, Blähungen","Nasenbluten","Erhöhte Leberwerte","Gewichtszunahme, Gicht","Erektionsstörungen"],"sehrSelten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Bradykardie, Herzrhythmusstörungen","Bronchospasmus","Leberentzündung, Cholestase (Gallenstau), Gelbsucht","Priapismus (schmerzhafte Dauererektion)","Verschwommenes Sehen, Haarausfall, Nesselsucht"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Kataraktoperation","Retrograde Ejakulation (Samenerguss in die Blase)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; es gibt kaum Erfahrungen bei Schwangeren.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Die erste Dosis kann starken Schwindel oder eine Ohnmacht auslösen – Behandlung mit niedriger Dosis beginnen, zu Beginn kein Auto fahren und langsam aufstehen.","Vor einer Operation am grauen Star die Augenärztin oder den Augenarzt über die Einnahme informieren.","Retardtabletten ganz schlucken, nicht teilen oder kauen; die leere Tablettenhülle kann im Stuhl erscheinen.","Bei einer schmerzhaften Dauererektion sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Retardtabletten"]},"doxorubicin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen und verhindert so deren Teilung. Doxorubicin lagert sich zwischen die DNA-Basenpaare ein (Interkalation), hemmt die Topoisomerase II und führt zu DNA-Strangbrüchen; zudem entstehen freie Sauerstoffradikale. Die Radikalbildung im Herzmuskel gilt als Hauptursache der dosisabhängigen Herzschädigung. In pegylierten Liposomen verpackt (Caelyx) zirkuliert der Wirkstoff länger, reichert sich stärker im Tumorgewebe an und schädigt das Herz weniger.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Neutropenie, Anämie, Thrombozytopenie","Infektionen","Haarausfall (bei konventionellem Doxorubicin meist vollständig)","Übelkeit, Erbrechen, Appetitlosigkeit","Mukositis, Stomatitis (Mund- und Schleimhautentzündung), Durchfall","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen, v. a. bei liposomalem Doxorubicin)","Fieber, Müdigkeit"],"haeufig":["Kardiomyopathie, Herzschwäche (dosisabhängig, auch Jahre später)","Herzrasen, Herzrhythmusstörungen","Bindehautentzündung (Konjunktivitis)","Juckreiz, Hautausschlag, Verfärbung von Haut und Nägeln","Lokale Reaktionen und Venenentzündung an der Injektionsstelle"],"unbekannt":["Akute myeloische Leukämie, myelodysplastisches Syndrom (Zweiterkrankung)","Anaphylaxie (schwere allergische Reaktion)","Thrombophlebitis, Thromboembolien","Gewebsnekrose bei Paravasat","Tumorlyse-Syndrom","Strahlen-Recall-Reaktion","Ausbleiben der Regelblutung, Unfruchtbarkeit"]},"schwangerschaft":"Fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – Doxorubicin geht in die Muttermilch über.","hinweise":["Der Urin kann sich 1–2 Tage nach der Gabe rötlich verfärben – das ist harmlos.","Herzfunktion vor Beginn und regelmässig kontrollieren; Atemnot, Herzklopfen oder geschwollene Beine melden – auch Jahre nach der Behandlung.","Konventionelles und liposomales Doxorubicin (Caelyx) sind nicht austauschbar.","Schmerzen oder Brennen an der Infusionsstelle sofort melden (Gefahr eines Paravasats)."],"darreichung":["Injektionslösung","Pulver zur Herstellung einer Injektionslösung","Liposomales Konzentrat zur Herstellung einer Infusionslösung"]},"doxycyclin":{"wirkmechanismus":"Hemmt das Wachstum und die Vermehrung von Bakterien. Doxycyclin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und verhindert die Anlagerung der Aminoacyl-tRNA; dadurch wird die Eiweissbildung der Bakterien blockiert (bakteriostatische Wirkung). Das Spektrum umfasst viele grampositive und gramnegative Keime sowie Erreger, die in Zellen leben, wie Chlamydien, Mykoplasmen und Rickettsien, ausserdem Borrelien. Doxycyclin ist gut fettlöslich, wird fast vollständig aufgenommen und reichert sich auch bei eingeschränkter Nierenfunktion kaum an.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Kopfschmerzen","Photosensibilität (sonnenbrandähnliche Hautreaktion bei Licht)","Hautausschlag","Überempfindlichkeitsreaktionen (z. B. Nesselsucht, Schwellungen, in schweren Fällen Anaphylaxie)"],"gelegentlich":["Dyspepsie (Sodbrennen, Magenschleimhautreizung)"],"selten":["Speiseröhrenentzündung und -geschwüre, Schluckbeschwerden","Durchfall, Bauchschmerzen, Zungenentzündung","Pseudomembranöse Kolitis (schwere Darmentzündung durch Clostridioides difficile)","Erhöhter Hirndruck (Pseudotumor cerebri) mit Kopfschmerzen und Sehstörungen","Leberentzündung, erhöhte Leberwerte","Blutbildveränderungen (hämolytische Anämie, Thrombozytopenie, Neutropenie)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Pankreatitis, Herzbeutelentzündung, Gelenk- und Muskelschmerzen, Ohrensausen"],"unbekannt":["Bleibende Zahnverfärbung und Zahnschmelzschäden bei Kindern unter 8 Jahren","Pilzinfektionen (Mund, Scheide)","Jarisch-Herxheimer-Reaktion (Fieber, Schüttelfrost) bei Borreliose oder Syphilis"]},"schwangerschaft":"Kontraindiziert: Doxycyclin kann beim ungeborenen Kind zu bleibender Zahnverfärbung und Störungen des Knochenwachstums führen, vor allem ab dem 4. Schwangerschaftsmonat.","stillzeit":"Kontraindiziert: geht in die Muttermilch über (Zahnverfärbung und Störung des Knochenwachstums beim Säugling möglich).","hinweise":["Mit einem grossen Glas Wasser in aufrechter Haltung einnehmen und danach mindestens 30 Minuten nicht hinlegen – nicht direkt vor dem Schlafengehen (Gefahr von Speiseröhrengeschwüren). Einnahme zu einer Mahlzeit verbessert die Magenverträglichkeit.","Calcium-, Magnesium-, Eisen- und Zinkpräparate sowie Antazida mit 2–3 Stunden Abstand einnehmen; grössere Mengen Milchprodukte nicht gleichzeitig.","Während der Behandlung und einige Tage danach starke Sonne und Solarium meiden, guten Sonnenschutz verwenden.","Bei starken Kopfschmerzen mit Sehstörungen oder bei schwerem, anhaltendem Durchfall sofort ärztlichen Rat einholen."],"darreichung":["Tabletten","Lösliche Tabletten"]},"dronedaron":{"wirkmechanismus":"Hilft, nach Vorhofflimmern den normalen Herzrhythmus zu halten, und bremst den Puls. Dronedaron ist ein mit Amiodaron verwandter Multikanalblocker ohne Jod: Es hemmt Kalium-, Natrium- und Calciumkanäle der Herzmuskelzellen und wirkt zusätzlich nicht kompetitiv antiadrenerg. Dadurch verlängern sich Aktionspotenzial und Refraktärzeit, und die Herzfrequenz sinkt. Es wird über CYP3A4 abgebaut und hemmt selbst CYP3A4, CYP2D6 und P-Glykoprotein.","nebenwirkungen":{"sehrHaeufig":["Erhöhtes Kreatinin im Blut","QT-Verlängerung im EKG","Neu auftretende oder verschlechterte Herzinsuffizienz"],"haeufig":["Bradykardie (langsamer Puls)","Durchfall, Erbrechen, Übelkeit, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Müdigkeit, Schwäche","Erhöhte Leberwerte"],"gelegentlich":["Interstitielle Lungenerkrankung (Pneumonitis, Lungenfibrose)","Geschmacksstörungen","Lichtempfindlichkeit der Haut, Ekzem, Hautrötung"],"selten":["Leberschäden bis zum lebensbedrohlichen akuten Leberversagen","Anaphylaxie und Angioödem","Geschmacksverlust","Gefässentzündung (Vaskulitis)"]},"schwangerschaft":"In Tierstudien fruchtschädigend; während der Schwangerschaft nicht empfohlen. Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Dronedaron in die Muttermilch übergeht (bei Tieren ja); entweder abstillen oder auf die Behandlung verzichten.","hinweise":["Zweimal täglich zum Frühstück und zum Abendessen einnehmen; keinen Grapefruitsaft trinken.","Regelmässige Kontrollen von EKG, Leber- und Nierenwerten.","Bei Zeichen einer Leberschädigung (Schmerzen im rechten Oberbauch, Gelbsucht, dunkler Urin) oder einer Herzschwäche (Atemnot, Gewichtszunahme, geschwollene Beine) sofort ärztliche Hilfe holen.","Vor jeder neuen Medikation Wechselwirkungen in der Apotheke prüfen lassen."],"darreichung":["Filmtabletten"]},"drospirenon":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem es den Eisprung unterdrückt. Drospirenon ist ein vom Spironolacton abgeleitetes Gestagen: Es hemmt die Ausschüttung von LH aus der Hirnanhangsdrüse und macht den Schleim im Gebärmutterhals für Spermien schwer durchlässig. Zusätzlich wirkt es antimineralokortikoid (fördert die Ausscheidung von Natrium und Wasser und hält Kalium zurück) und antiandrogen.","nebenwirkungen":{"haeufig":["Zwischenblutungen, unregelmässige oder ausbleibende Blutungen","Regelschmerzen","Akne","Kopfschmerzen","Brustschmerzen","Übelkeit, Bauchschmerzen","Libidoabnahme, Stimmungsschwankungen","Gewichtszunahme"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)","Eierstockzysten","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nicht anwenden. Tritt unter der Einnahme eine Schwangerschaft ein, absetzen; Hinweise auf Fehlbildungen nach versehentlicher Einnahme gibt es nicht.","stillzeit":"Als reines Gestagenpräparat nach ärztlicher Beratung möglich (geringe Mengen in der Muttermilch, keine Beeinträchtigung der Milchbildung). Kombinationen mit Östrogen in der Stillzeit nicht empfohlen.","hinweise":["Täglich zur gleichen Zeit einnehmen (24 Hormon- und 4 wirkstofffreie Tabletten ohne Pause).","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall Packungsbeilage beachten – gegebenenfalls zusätzlich Kondome verwenden.","Unregelmässige Blutungen sind besonders in den ersten Monaten häufig; anhaltende oder starke Blutungen ärztlich abklären lassen.","Bei eingeschränkter Nierenfunktion und gleichzeitiger Einnahme kaliumerhöhender Mittel Kalium kontrollieren lassen."],"darreichung":["Filmtabletten"]},"dulaglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1, das nach dem Essen ausgeschüttet wird. Dulaglutid besteht aus zwei GLP-1-ähnlichen Peptidketten, die an ein verändertes Antikörperstück (Fc-Teil von IgG4) gekoppelt sind; dadurch wird es nur langsam abgebaut und wirkt eine Woche lang. Es steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und verstärkt das Sättigungsgefühl. In einer grossen Studie senkte es bei Typ-2-Diabetes das Risiko schwerer Herz-Kreislauf-Ereignisse.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen","Bauchschmerzen","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoff"],"haeufig":["Appetitminderung","Verdauungsbeschwerden, Verstopfung, Blähungen, Völlegefühl, Reflux, Aufstossen","Müdigkeit (Fatigue)","Sinustachykardie (erhöhter Puls)","AV-Block 1. Grades (leichte Verzögerung der Erregungsleitung im Herzen, im EKG sichtbar)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Dehydratation (Flüssigkeitsmangel)","Gallensteine (Cholelithiasis) und Cholezystitis (Gallenblasenentzündung)","Reaktionen an der Injektionsstelle"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Nicht-mechanischer Darmverschluss (Ileus)"]},"schwangerschaft":"Nicht anwenden: Die Erfahrungen sind unzureichend, Tierversuche zeigten Fruchtschädigung. Bei Diabetes in der Schwangerschaft wird Insulin eingesetzt.","stillzeit":"Nicht anwenden, da nicht bekannt ist, ob Dulaglutid in die Muttermilch übergeht.","hinweise":["Einmal pro Woche am gleichen Wochentag spritzen, unabhängig vom Essen; der Wochentag kann gewechselt werden, wenn seit der letzten Dosis mindestens 3 Tage vergangen sind.","Vergessene Dosis nachholen, wenn bis zur nächsten planmässigen Dosis noch mindestens 3 Tage (72 Stunden) bleiben, sonst auslassen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen; bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (Einzeldosis)"]},"duloxetin":{"wirkmechanismus":"Hellt die Stimmung auf und dämpft die Schmerzweiterleitung, indem es die Botenstoffe Serotonin und Noradrenalin im Nervensystem länger wirken lässt. Duloxetin hemmt die Wiederaufnahme von Serotonin und Noradrenalin etwa gleich stark, Dopamin nur schwach. An histaminergen, dopaminergen, cholinergen und adrenergen Rezeptoren wirkt es kaum. Die schmerzlindernde Wirkung beruht auf der Verstärkung absteigender, schmerzhemmender Nervenbahnen im Rückenmark.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schläfrigkeit","Mundtrockenheit"],"haeufig":["Schwindel, Zittern, Kribbeln, Müdigkeit","Appetitminderung, Gewichtsabnahme","Schlaflosigkeit, Unruhe, Angst, abnorme Träume","Verminderte Libido, Orgasmus-, Erektions- und Ejakulationsstörungen","Verstopfung, Durchfall, Bauchschmerzen, Erbrechen, Dyspepsie (Verdauungsbeschwerden)","Herzklopfen, Blutdruckanstieg, Hitzewallungen","Vermehrtes Schwitzen, Hautausschlag","Verschwommenes Sehen, Ohrensausen, Muskelschmerzen und -krämpfe"],"gelegentlich":["Suizidgedanken","Herzrasen, Vorhofflimmern, Ohnmacht","Magen-Darm-Blutungen, Blutergüsse, Nasenbluten","Hepatitis, erhöhte Leberwerte, akute Leberschädigung","Erhöhter Blutzucker","Harnverhalt, erschwertes Wasserlassen","Lichtempfindlichkeit, Nesselsucht"],"selten":["Anaphylaxie, Angioödem","Hyponatriämie (Natriummangel), SIADH","Serotoninsyndrom, Krampfanfälle","Manie, Halluzinationen, Aggressivität, suizidales Verhalten","Leberversagen, Gelbsucht","Hypertensive Krise, Glaukom","Stevens-Johnson-Syndrom","Interstitielle Lungenerkrankung, eosinophile Pneumonie"],"sehrSelten":["Hautvaskulitis (Entzündung kleiner Hautgefässe)"],"unbekannt":["Stress-Kardiomyopathie (Takotsubo)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungsstörungen und Entzugssymptome sowie bei der Mutter ein erhöhtes Risiko für Nachblutungen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen wird nicht empfohlen.","hinweise":["Kapseln unzerkaut schlucken, nicht öffnen (magensaftresistenter Inhalt).","Nicht abrupt absetzen, sondern über mindestens 2 Wochen ausschleichen (Absetzsymptome wie Schwindel, Kribbeln, Übelkeit).","Blutdruck und Puls regelmässig kontrollieren; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen ärztlich abklären lassen (Leber).","Viel Alkohol meiden (Leberschäden); die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Magensaftresistente Kapseln"]},"dupilumab":{"wirkmechanismus":"Hemmt gezielt eine bestimmte Art der allergischen Entzündung (Typ-2-Entzündung). Dupilumab ist ein menschlicher Antikörper, der an die Alpha-Untereinheit des Interleukin-4-Rezeptors bindet. Dadurch werden die Signale der Botenstoffe Interleukin-4 und Interleukin-13 blockiert, die Juckreiz, Ekzeme, Schleimbildung und Verengung der Atemwege fördern. Der Antikörper wird wie körpereigene Eiweisse abgebaut, nicht über die Leber-Enzyme.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz, Schmerz)"],"haeufig":["Bindehautentzündung (Konjunktivitis), auch allergisch","Augenjucken, Lidrandentzündung (Blepharitis)","Lippenherpes","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Gelenkschmerzen"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Keratitis (Hornhautentzündung)","Trockenes Auge","Gesichtsrötung oder -ausschlag"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Serumkrankheit","Ulzerative Keratitis (Hornhautgeschwür)"]},"schwangerschaft":"Nur wenn der Nutzen das mögliche Risiko überwiegt; die Erfahrungen sind begrenzt, Tierversuche zeigen keine schädlichen Wirkungen.","stillzeit":"Unbekannt, ob Dupilumab in die Muttermilch übergeht; Entscheidung über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 1–4 Wochen unter die Haut gespritzt; nach Schulung auch selbst zu Hause möglich. Fertigspritze vor Gebrauch Raumtemperatur annehmen lassen.","Andere Asthma- oder Neurodermitis-Mittel nicht eigenmächtig absetzen.","Bei geröteten, juckenden oder schmerzenden Augen oder Sehstörungen ärztlich abklären lassen."],"darreichung":["Fertigspritze","Fertigpen"]},"dutasterid":{"wirkmechanismus":"Lässt eine vergrösserte Prostata schrumpfen, indem es die Bildung des stark wirksamen Androgens Dihydrotestosteron (DHT) unterdrückt. Dutasterid hemmt beide Formen des Enzyms 5-Alpha-Reduktase (Typ 1 und Typ 2), die Testosteron in DHT umwandeln; der DHT-Spiegel im Blut sinkt um über 90 %. Das Prostatavolumen nimmt über Monate ab, die Beschwerden bessern sich meist nach 3–6 Monaten. Wegen der sehr langen Halbwertszeit von etwa 5 Wochen bleibt der Wirkstoff nach dem Absetzen noch monatelang im Körper.","nebenwirkungen":{"haeufig":["Erektionsstörung (Impotenz)","Verminderte Libido (Lust auf Sex)","Ejakulationsstörungen, z. B. vermindertes Spermavolumen","Brustbeschwerden (Spannungsgefühl, Vergrösserung)","Schwindel (in Kombination mit Tamsulosin)"],"gelegentlich":["Haarausfall (v. a. Körperbehaarung) oder vermehrter Haarwuchs"],"unbekannt":["Herzinsuffizienz (in Studien, v. a. in Kombination mit Alpha-Blockern)","Überempfindlichkeitsreaktionen mit Ausschlag, Juckreiz, Nesselsucht, Angioödem","Depressive Verstimmung","Hodenschmerzen und Hodenschwellung","Brustkrebs beim Mann"]},"schwangerschaft":"Kontraindiziert. Der Wirkstoff wird über die Haut aufgenommen: Frauen, Kinder und Jugendliche sollen beschädigte, undichte Kapseln nicht berühren (sonst die Haut sofort mit Wasser und Seife waschen). Da Dutasterid ins Sperma übergeht, soll ein Kondom benutzt werden, wenn die Partnerin schwanger ist oder schwanger werden könnte.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Kapseln ganz schlucken, nicht kauen oder öffnen – der Inhalt reizt die Schleimhaut von Mund und Rachen.","Während der Behandlung und bis mindestens 6 Monate nach der letzten Einnahme kein Blut spenden.","Bei einer PSA-Bestimmung die Einnahme angeben.","Die Wirkung ist oft erst nach 3–6 Monaten spürbar; nicht vorzeitig absetzen."],"darreichung":["Weichkapseln"]},"dutasterid-tamsulosin":{"wirkmechanismus":"Erleichtert das Wasserlösen auf zwei Wegen. Tamsulosin blockiert Alpha-1A-Rezeptoren in Prostata und Blasenhals und entspannt die glatte Muskulatur – das wirkt innert Tagen. Dutasterid hemmt beide Formen der 5-Alpha-Reduktase und damit die Umwandlung von Testosteron in Dihydrotestosteron; die Prostata schrumpft über Monate. Beide Wirkstoffe werden über CYP3A4 abgebaut, Tamsulosin zusätzlich über CYP2D6.","nebenwirkungen":{"haeufig":["Erektionsstörungen","Verminderte Libido","Ejakulationsstörungen (z. B. vermindertes Ejakulatvolumen)","Brustvergrösserung oder -spannen beim Mann","Schwindel"],"gelegentlich":["Herzinsuffizienz","Kopfschmerzen, Herzklopfen","Blutdruckabfall beim Aufstehen","Schnupfen","Verstopfung, Durchfall, Übelkeit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Schwächegefühl"],"selten":["Ohnmacht (Synkope)","Angioödem (Schwellung von Haut und Schleimhäuten)"],"sehrSelten":["Priapismus (schmerzhafte Dauererektion)","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Augenoperationen","Depression","Hodenschmerzen und -schwellung","Sehstörungen, Nasenbluten, Mundtrockenheit","Erythema multiforme, Hautablösung"]},"schwangerschaft":"Nur für Männer. Schwangere und Frauen, die schwanger werden könnten, dürfen undichte Kapseln nicht berühren (Dutasterid wird über die Haut aufgenommen und kann männliche Föten schädigen).","stillzeit":"Nicht anwendbar (nur für Männer).","hinweise":["Kapsel ganz schlucken, nicht öffnen oder kauen; täglich 30 Minuten nach derselben Mahlzeit einnehmen.","Die volle Wirkung auf die Prostata zeigt sich erst nach 3–6 Monaten.","Vor einer Augenoperation (grauer Star) die Einnahme angeben.","Während der Behandlung und bis 6 Monate danach kein Blut spenden; Kondom verwenden, wenn die Partnerin schwanger ist oder werden könnte."],"darreichung":["Hartkapseln"]},"dydrogesteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon und bringt die Gebärmutterschleimhaut in die zweite Zyklusphase. Dydrogesteron ist ein oral wirksames Retroprogesteron, das sehr selektiv an Progesteronrezeptoren bindet und die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut umwandelt. Es hat keine östrogene, androgene oder kortisonartige Wirkung und hemmt in üblicher Dosis den Eisprung nicht. Sein Hauptabbauprodukt (20-alpha-Dihydrodydrogesteron) ist ebenfalls gestagen wirksam.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Übelkeit","Menstruationsstörungen (Zwischenblutungen, starke, schmerzhafte oder ausbleibende Blutungen)","Brustschmerzen oder Brustspannen"],"gelegentlich":["Depressive Verstimmung","Schwindel","Erbrechen","Leberfunktionsstörungen, teils mit Gelbsucht, Schwäche und Bauchschmerzen","Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gewichtszunahme"],"selten":["Hämolytische Anämie (Blutarmut durch Zerfall roter Blutkörperchen)","Überempfindlichkeitsreaktionen","Schläfrigkeit","Angioödem (Schwellung von Gesicht und Rachen)","Wassereinlagerungen (Ödeme)","Brustschwellung","Grössenzunahme gestagenabhängiger Tumoren (z. B. Meningeom)"]},"schwangerschaft":"Je nach Präparat bei drohender Fehlgeburt infolge nachgewiesenen Progesteronmangels zugelassen und nur auf ärztliche Verordnung anzuwenden; ein schädigender Einfluss auf das Kind ist nicht belegt. Kombinationen mit Östrogen (Femoston) sind in der Schwangerschaft nicht angezeigt.","stillzeit":"Nicht anwenden – es ist nicht bekannt, ob Dydrogesteron in die Muttermilch übergeht.","hinweise":["Tabletten unabhängig von den Mahlzeiten mit etwas Flüssigkeit einnehmen; den vorgegebenen Zyklustagen genau folgen.","Dydrogesteron hemmt den Eisprung nicht und schützt nicht vor einer Schwangerschaft.","Bei Hormonersatz Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen; ungewöhnliche Blutungen abklären lassen."],"darreichung":["Filmtabletten"]}});
